// GENDER WARFARE: local-file-safe dialogue cache, generated from data/dialogue/*.json.
window.GW_DIALOGUE_DATA = {"F1":{"chapter":"F1","title":"항만 탈환","line":"female","episodes":[{"id":"F1-1","no":1,"title":"부두의 첫 정화","boss":false,"before":[{"who":"클레어","text":"남부 항구가 제국 해군 특수 상륙대에 점령당했습니다. 홍차는 식기 전에 마시고, 정화는 식기 전에 시작하겠습니다."},{"who":"제국 병사 A","text":"정화라고? 그건 우리 쪽 대사다!"},{"who":"클레어","text":"정화는 연방이 먼저 상표를 등록했어요."},{"who":"제국 병사 B","text":"상표는 우리가 먼저였어! 그리고 우리 도구가 더 크다!"},{"who":"아네트","text":"사이즈 비교는 포획하고 해 보죠."},{"who":"제국 병사 B","text":"이래 뵈도 큰 편이란 말이다!! (당황한다)"},{"who":"실비아","text":"(스코프를 들여다보며) …어디 있다는 거죠? 안 보이는데요."},{"who":"그레타","text":"확대율을 올려 주면 되겠구만."},{"who":"클레어","text":"실비아, 감정은 나중에. 지금은 교전 규칙부터 안내하겠습니다. 포획 후 정화, 정화 후 계약, 계약 후 예약입니다."}],"after":[{"who":"아네트","text":"포획 32명. 이송 전에 접수대에서 번호표를 뽑아 주세요."},{"who":"제국 병사 A","text":"번호표…… 이거 줄이 왜 이렇게 길어?"},{"who":"그레타","text":"자네들이 먼저 서겠다고 해서 그런 거 아니구만."},{"who":"제국 병사 B","text":"(조용히) …내 번호 몇 번이지?"},{"who":"클레어","text":"업무가 빠르시네요. 다들 정리되면 차를 한 잔씩 드리겠습니다."}],"stars":{"1":{"who":"아네트","text":"병사 일부가 접수 전에 흩어졌습니다. 아쉽게도 상담 불가입니다."},"2":{"who":"아네트","text":"포획은 양호했으나 접수 줄이 길어졌습니다. 번호표를 늘리겠습니다."},"3":{"who":"아네트","text":"오차 없는 포획입니다. 접수 대기시간 평균 4분, 만족도 상."}}},{"id":"F1-2","no":2,"title":"크레인 위의 높은 분들","boss":false,"before":[{"who":"아네트","text":"제국 장교단이 부두 크레인 위에서 지휘 중입니다. 지상까지 약 30미터입니다."},{"who":"그레타","text":"높은 데서 거드름 피우는 건 하나같이 밑이 약하구만."},{"who":"클레어","text":"내려오시게 하는 것이 먼저죠. 실비아."},{"who":"실비아","text":"예의 바르게 말씀드리겠습니다. 허리띠를 끊겠습니다. 한 분당 한 발입니다."},{"who":"제국 장교","text":"우리는 이 높이를 지킬 것이다! 아래 것들이 올려다보는 이 풍경이 군인의 낙이다!"},{"who":"그레타","text":"올려다보는 쪽은 그쪽 바지 사정이 잘 보이겠구만."},{"who":"제국 장교","text":"…바지?"}],"after":[{"who":"","kind":"stage","text":"(화면 밖: 투둑, 투둑, 투두둑)"},{"who":"제국 장교","text":"내려가는 건가? 내려가면 어떻게 되는 거지? 아니, 내려가고 싶은 건 아니고 확인차 묻는 거다."},{"who":"클레어","text":"내려오시면 상담소 안내를 받으시게 됩니다."},{"who":"제국 장교","text":"…안내가 길지는 않겠지?"},{"who":"아네트","text":"평균 40분입니다. 간식 제공."},{"who":"제국 장교","text":"사십 분이나!"}],"stars":{"1":{"who":"아네트","text":"허리띠 몇 개가 바다에 빠졌습니다. 예비 허리띠를 지급하겠습니다."},"2":{"who":"아네트","text":"장교 대부분 하강. 일부는 크레인 위에서 아직 기다리고 계십니다."},"3":{"who":"아네트","text":"장교 전원 하강. 허리띠 회수율 100%, 간식 만족도 최상."}}},{"id":"F1-3","no":3,"title":"컨테이너의 매뉴얼","boss":false,"before":[{"who":"그레타","text":"컨테이너 안에서 제국 문서가 나왔구만. 표지가 「정화 매뉴얼 제3판」이야."},{"who":"클레어","text":"제목이 낯익군요. 우리 규정집 제목과 한 글자 차이입니다."},{"who":"아네트","text":"(훑으며) 내용도 거의 같네요. 제3조 4항 「주인은 노예가 가장 편한 위치에 도구를 고정한다」. 저희 규정은 「주인이 가장 잡기 편한 위치」입니다."},{"who":"그레타","text":"서로 한 글자씩 바꿔 베꼈구만. 누가 먼저인지 아무도 모르는 게 웃기는 일이야."},{"who":"실비아","text":"저는 제5조가 마음에 듭니다. 「도구는 소리가 좋아야 한다」."},{"who":"제국 병사","text":"그건 저희 취향입니다!"},{"who":"클레어","text":"취향이 겹치면 대화가 빠르죠. 교전 전에 감상 한마디씩 나누시겠습니까?"}],"after":[{"who":"제국 병사","text":"3판은 오탈자가 너무 많습니다. 개정안을 올리고 싶습니다."},{"who":"아네트","text":"환영합니다. 저희도 4판을 준비 중이에요. 공동 편집 신청서는 접수대에서 받으세요."},{"who":"그레타","text":"적과 같이 규정집을 만들고 있구만. 이게 전쟁인가."},{"who":"클레어","text":"전쟁입니다. 다만 서식이 있을 뿐이죠."}],"stars":{"1":{"who":"아네트","text":"문서 일부가 젖었습니다. 읽을 수 있는 곳만 읽겠습니다."},"2":{"who":"아네트","text":"문서 대부분 회수. 오탈자 몇 건이 남았습니다."},"3":{"who":"아네트","text":"문서 전량 회수, 오탈자 42건 수정 완료."}}},{"id":"F1-4","no":4,"title":"야전 상담소","boss":false,"before":[{"who":"아네트","text":"오늘부터 이동식 정화 조련실을 가동합니다. 공식 명칭은 「야전 상담소」입니다."},{"who":"클레어","text":"접수대와 대기석도 갖췄군요. 이름은 잘 지으셨어요."},{"who":"아네트","text":"이용은 예약제입니다. 오늘은 신규 환자 20명이 대기 중이에요."},{"who":"제국 병사","text":"(줄 서며) 저 앞 사람 새치기입니다! 제 번호가 먼저예요!"},{"who":"그레타","text":"전투 중에 새치기 싸움이구만."},{"who":"실비아","text":"저도 예약을 걸고 싶습니다. 정중하게 부탁드립니다."},{"who":"아네트","text":"실비아 씨는 진료실이 아니라 간호 담당이시죠. 접수는 제가 하겠습니다."},{"who":"실비아","text":"…그럼 구경만이라도."}],"after":[{"who":"아네트","text":"오늘 진료 20건 완료. 평균 소요 8분, 재방문 의사 100%."},{"who":"제국 병사","text":"(나오며) 선생님, 다음 예약은 언제입니까?"},{"who":"아네트","text":"다음 주 같은 시간입니다. 가운은 두고 가세요."},{"who":"제국 병사","text":"…가운이 좋아서 못 두고 가겠습니다."},{"who":"클레어","text":"반납은 다음 방문 때 부탁드립니다."}],"stars":{"1":{"who":"아네트","text":"새치기가 발생해 일부 진료가 지연되었습니다."},"2":{"who":"아네트","text":"진료는 순조로웠으나 대기석이 가득 찼습니다."},"3":{"who":"아네트","text":"대기 0분, 접수 오류 0건. 상담소 만족도 5점 만점."}}},{"id":"F1-5","no":5,"title":"딸 사진 병장","boss":false,"before":[{"who":"아네트","text":"제국 의무 병장이 접근 중입니다. 이름은 톰, 41세. 가족 사진첩을 들고 다닌다는 보고가 있습니다."},{"who":"톰","text":"(손을 들며) 전투 전에 잠깐만요. 우리 딸 사진 한 장만 보고 가세요. 이게 지난 가을 운동회인데요."},{"who":"그레타","text":"전장에서 사진첩을 펼치는 병장은 처음 보구만."},{"who":"톰","text":"이쪽은 학예회, 이쪽은 졸업식. 그러니까 제 말씀은 우리 딸이 어른이 되어 가는 걸 보면서도 저는 아직 어른이 못 된 기분이 들어서요."},{"who":"클레어","text":"따님 이야기를 좋아하시는군요. 아네트, 초커를."},{"who":"톰","text":"초커요? 아, 목에 두르는 거요? 잠깐, 그건 처음 보는 건데……"}],"after":[{"who":"","kind":"stage","text":"(화면 밖: 철컥)"},{"who":"톰","text":"어, 이거 목이 허전했는데 딱 맞네요. 담요 하나 가져가도 됩니까?"},{"who":"아네트","text":"짐꾼 직군으로 전향하시겠어요?"},{"who":"톰","text":"네, 짐은 잘 듭니다. 딸 사진이랑 담요랑 그리고 이 초커랑 같이요."},{"who":"그레타","text":"적응이 너무 빨라서 오히려 이쪽이 당황하구만."},{"who":"클레어","text":"톰 병장님, 합류를 환영합니다. 첫 임무는 홍차 운반입니다."}],"stars":{"1":{"who":"아네트","text":"합류했지만 딸 사진 발표가 길었습니다. 다음에는 3분 제한을 두겠습니다."},"2":{"who":"아네트","text":"합류는 완료되었으나 사진첩 보여주기 시간이 15분 초과했습니다."},"3":{"who":"아네트","text":"톰 병장님 합류. 초커 착용감 만족도 최상, 담요 추가 지급."}}},{"id":"F1-6","no":6,"title":"짐꾼의 규정 거리","boss":false,"before":[{"who":"아네트","text":"톰 병장님께 마도 족쇄를 장착했습니다. 주인과 노예 사이 3미터 이상 떨어지면 당겨 주는 규정입니다."},{"who":"톰","text":"당겨 준다고요? 근데 꼭 「여기」 묶으실 필요가 있습니까…… ㅜ.ㅜ"},{"who":"아네트","text":"「거기」가 잡기 편해서요."},{"who":"클레어","text":"…아네트, 장착 위치는 규정에 명시되어 있습니까?"},{"who":"아네트","text":"제3조 4항, 「주인이 가장 잡기 편한 위치」입니다. 저는 잡기 편한 위치에 두었을 뿐이에요."},{"who":"그레타","text":"위치가 거기면 당겼을 때 3미터 규정이 아주 확실하게 지켜지겠구만."},{"who":"실비아","text":"저는 어디인지 확인했습니다. 설명은 필요 없습니다. 시선은 이미 한 번 다녀왔습니다."},{"who":"톰","text":"다들 확인하지 마세요, 부끄러운 건 아닌데 괜히 자랑하는 기분이라서요."}],"after":[{"who":"톰","text":"3미터 넘으니까 당겨졌어요. 아, 그런데 은근히 좋네요. 다음엔 5미터 정도에서도 시험해 봐도 될까요?"},{"who":"아네트","text":"규정 개정 신청서를 쓰시면 됩니다. 간이 접수는 제가 대신 하겠습니다."},{"who":"클레어","text":"규정은 현장에서 자랍니다."}],"stars":{"1":{"who":"아네트","text":"이탈 다수. 족쇄가 더 필요하다는 의견이 접수되었습니다."},"2":{"who":"아네트","text":"이탈 2회. 당김 반응은 정상, 의견: 「조금 더」."},"3":{"who":"아네트","text":"이탈 0회, 당김 반응 우수. 톰 병장님 의견: 「만족」."}}},{"id":"F1-7","no":7,"title":"잠수함에서 나온 사냥개","boss":false,"before":[{"who":"아네트","text":"잠수함 한 척이 부두 아래로 접근했습니다. 해군 중위 렌, 예리한 저격 성향입니다."},{"who":"렌","text":"이 부두는 제국 해군이 장악한다. 항복은 없다. 수염 하나 흔들리지 않겠다."},{"who":"그레타","text":"수염이 없는 얼굴이구만."},{"who":"렌","text":"비유다. 나는 굳건하다."},{"who":"클레어","text":"(하이힐 소리, 또각) 중위님. 이쪽을 보세요."},{"who":"렌","text":"…굽이 높군. 전술적으로 위험하다."},{"who":"클레어","text":"위험하신가요. 그럼 가까이서 살펴보시죠."}],"after":[{"who":"렌","text":"항복이 아니다. 전술적 후퇴다. 다만 군복이 갑자기 답답하다."},{"who":"아네트","text":"체온이 올랐습니다. 이마가 뜨거운데 확인하시겠어요?"},{"who":"렌","text":"확인은 필요 없다. …확인하고 싶다면 해라."},{"who":"클레어","text":"합류를 환영합니다, 렌 중위님."},{"who":"렌","text":"나는 합류하는 게 아니라 압송되는 것이다. 이 목줄도 임시다."},{"who":"그레타","text":"이미 손으로 만지고 있구만."}],"stars":{"1":{"who":"아네트","text":"합류했지만 아직 항복 의사를 밝히지 않았습니다. 단, 목줄은 풀지 않았습니다."},"2":{"who":"아네트","text":"합류 완료. 저항 의지는 유지되었으나 시선이 하이힐에 고정됩니다."},"3":{"who":"아네트","text":"렌 중위님 합류. 체온 38.2도, 저항 의지 유지, 몸은 정직."}}},{"id":"F1-8","no":8,"title":"노예 팀 점호","boss":false,"before":[{"who":"아네트","text":"노예 팀 점호입니다. 서열은 입소 순입니다. 톰 병장님이 선임, 렌 중위님이 후임입니다."},{"who":"렌","text":"계급은 내가 높다. 병장이 선임이라는 건 군의 질서에 어긋난다."},{"who":"아네트","text":"이 소속에서는 「노예 서열이 계급보다 앞선다」가 규정입니다."},{"who":"톰","text":"렌 중위님, 후임으로서 담요를 개어 주시겠어요?"},{"who":"렌","text":"…내가 개켜야 하나."},{"who":"톰","text":"개켜 주시면 제가 선임으로서 머리 한 번 쓰다듬어 드릴게요."},{"who":"렌","text":"그런 보상은 필요 없다. …해 보게."}],"after":[{"who":"톰","text":"렌 중위님, 담요 접는 솜씨가 훌륭합니다."},{"who":"렌","text":"당연하다. 군인은 모서리를 맞춘다. (귀 끝이 붉어진다)"},{"who":"그레타","text":"후임이 칭찬받고 얼굴이 빨개지는 건 처음 보는구만."},{"who":"클레어","text":"팀워크가 형성되고 있네요. 내일 보스전을 앞두고 안심됩니다."}],"stars":{"1":{"who":"아네트","text":"점호 지연. 선후임 간 대화가 길어졌습니다."},"2":{"who":"아네트","text":"점호 양호. 후임 얼굴 붉음 정도 중."},"3":{"who":"아네트","text":"점호 완벽. 담요 모서리 오차 0."}}},{"id":"F1-9","no":9,"title":"전야의 점검","boss":false,"before":[{"who":"아네트","text":"내일은 보스전입니다. 족쇄와 초커를 점검합니다. 톰 병장님부터."},{"who":"톰","text":"네, 다 조여 주세요. 오늘은 딸이 꿈에서 칭찬해 주길 바라서요."},{"who":"아네트","text":"장력 90%. 규정 범위입니다."},{"who":"렌","text":"내 것도 점검해 봐라. 이상 없을 것이다."},{"who":"아네트","text":"장력 82%. 조금 헐거우시네요."},{"who":"렌","text":"헐거운 것이 효율적이다. …아니, 조금 더 조여도 괜찮다."},{"who":"실비아","text":"저도 점검받고 싶습니다. 정중하게 부탁드립니다."},{"who":"클레어","text":"실비아는 주인입니다. 다음에 하시죠."}],"after":[{"who":"톰","text":"푹 잘 수 있겠네요. 렌 중위님도 담요 덮으세요."},{"who":"렌","text":"덮겠다. (이불 속에서 작게) …따뜻하다."},{"who":"클레어","text":"모두 좋은 밤 되세요. 내일은 큰 배입니다."}],"stars":{"1":{"who":"아네트","text":"일부 족쇄 재조정이 필요합니다. 야간 근무자를 배치합니다."},"2":{"who":"아네트","text":"점검 합격, 일부 대원이 잠들기까지 오래 걸렸습니다."},"3":{"who":"아네트","text":"점검 전원 합격, 수면 상태 양호."}}},{"id":"F1-10","no":10,"title":"철갑 바다코끼리","boss":true,"before":[{"who":"클레어","text":"제국 증기 상륙함 「철갑 바다코끼리」. 갑판 위의 사령관 목소리가 스피커로 들립니다."},{"who":"제독(목소리)","text":"짐은 투항하지 않는다! 이 함선이 침몰해도 마지막까지 항전하겠다!"},{"who":"그레타","text":"목소리만 있고 얼굴이 안 보이는구만."},{"who":"제독(목소리)","text":"이름도 공개하지 않겠다. 다만 대기 번호는 1번이다."},{"who":"아네트","text":"투항도 안 하는데 대기 번호는 있으시군요."},{"who":"제독(목소리)","text":"소문을 들었다. 야전 상담소가 서비스가 좋다고."}],"after":[{"who":"제독(목소리)","text":"짐은 졌다. 여기서부터는 대기 번호대로 진행해 주길 바란다."},{"who":"클레어","text":"1번이시니 가장 먼저 모시겠습니다. 이름은 나중에 적으세요."},{"who":"톰","text":"제독님 목소리가 되게 떨리는데 괜찮으신가요?"},{"who":"제독(목소리)","text":"기대돼서 그렇다. …아니, 군인으로서 긴장해서 그렇다."},{"who":"클레어","text":"1장 종료입니다. 항만이 탈환되었습니다."}],"stars":{"1":{"who":"아네트","text":"상륙함이 반파되었습니다. 제독은 아직 바다 위에서 대기 중입니다."},"2":{"who":"아네트","text":"상륙함 격침. 제독은 구명정으로 이탈 중, 곧 재접수가 예상됩니다."},"3":{"who":"아네트","text":"제독 포획. 대기 번호 1번 확정, 접수 완료."}}}]},"F2":{"chapter":"F2","title":"공방 전선","line":"female","episodes":[{"id":"F2-1","no":1,"title":"잠든 공장의 점호","boss":false,"before":[{"who":"아네트","text":"연방 북부 폐공장 단지입니다. 제국이 증기 갑주 공방으로 개조했어요. 점호부터 하겠습니다. 톰 병장님, 렌 중위님, 상태 보고."},{"who":"톰","text":"좋습니다. 어제 담요 속에서 푹 잤고요, 오늘 아침엔 초커가 안 채워져 있어서 허전했습니다."},{"who":"렌","text":"이상 없다. 다만 어젯밤 이후로 몸이 떨린다. 군인의 자존심으로 인정하지 않겠다."},{"who":"클레어","text":"공방 근처라 더운 편인데요."},{"who":"렌","text":"…자존심이 추운 것이다."},{"who":"제국 병사들","text":"(훈도시 장갑복 차림으로 우르르 등장) 크하하! 여기서부터는 지나갈 수 없다!"},{"who":"그레타","text":"장갑이 위에만 있구만. 아래는 천 한 장이야."},{"who":"실비아","text":"정중하게 말씀드립니다. 시선을 어디에 둬야 할지 정해야겠습니다. 정면으로 가겠습니다."}],"after":[{"who":"그레타","text":"장갑이 위에만 있으니 두들길 데가 없어서 허탈하구만."},{"who":"아네트","text":"포획 인원 20명, 전원 방어력 저하. 상담소로 이송합니다."},{"who":"톰","text":"담요 덮어 줄까 했는데 다들 이미 만족한 표정이라 뭘 덮어야 할지 모르겠어요."},{"who":"렌","text":"나는 아직 자존심이 춥다."}],"stars":{"1":{"who":"아네트","text":"포획 지연. 천 한 장의 방어력이 의외로 높았습니다."},"2":{"who":"아네트","text":"포획 양호. 일부 병사가 훈도시를 잃고 자진 이송되었습니다."},"3":{"who":"아네트","text":"포획 완벽, 병사 전원 번호표 수령."}}},{"id":"F2-2","no":2,"title":"벨트 없는 사수","boss":false,"before":[{"who":"아네트","text":"공장 지붕 위 제국 사수들입니다. 모두 가죽 멜빵으로 총을 고정하고 있어요."},{"who":"실비아","text":"예의 바르게 말씀드리겠습니다. 멜빵 끈만 끊겠습니다. 방아쇠는 건드리지 않습니다."},{"who":"제국 사수","text":"끈이 끊어지면 총을 못 들잖아!"},{"who":"실비아","text":"총을 못 드시면 손이 비게 됩니다. 비면 다른 걸 드실 수 있습니다."},{"who":"그레타","text":"무슨 뜻이야."},{"who":"실비아","text":"문자 그대로입니다."}],"after":[{"who":"제국 사수","text":"총이 바닥에 떨어졌다. 이제 뭘 들면 되지?"},{"who":"아네트","text":"이쪽에 초커가 있습니다. 들어 보시겠어요?"},{"who":"제국 사수","text":"들겠습니다."},{"who":"실비아","text":"감사합니다. 정중한 일 처리였습니다."}],"stars":{"1":{"who":"아네트","text":"끈 절단 일부 실패. 사수 한 분이 아직 총을 안고 계십니다."},"2":{"who":"아네트","text":"끈 절단 양호. 일부 사수가 총을 놓고 바지를 붙들었습니다."},"3":{"who":"아네트","text":"끈 절단 100%, 방아쇠 손상 0."}}},{"id":"F2-3","no":3,"title":"컨베이어는 멈추지 않는다","boss":false,"before":[{"who":"클레어","text":"이 공장 컨베이어는 제국 증기 갑주를 24시간 찍어 냅니다. 멈추려면 중앙 레버를 내려야 해요."},{"who":"그레타","text":"레버 위에 병사들이 줄줄이 실려 오는구만. 벨트 위에서 싸울 순 없지."},{"who":"톰","text":"벨트가 빠르네요. 담요 위에 앉아서 가면 어떨까요?"},{"who":"렌","text":"담요는 부품이 아니다. 앉지 마라."},{"who":"아네트","text":"벨트 속도 시속 12킬로. 병사가 넘어지면 그대로 용광로입니다."},{"who":"제국 병사","text":"우릴 용광로로 보낼 셈이냐!"},{"who":"그레타","text":"안 보내. 그냥 상담소로 새게 하는 거야."}],"after":[{"who":"클레어","text":"레버를 내렸습니다. 공장이 조용해졌군요."},{"who":"제국 병사","text":"컨베이어가 서자 갑자기 허전합니다. 다시 돌려 주시면 안 됩니까?"},{"who":"아네트","text":"천천히 돌릴 수는 있습니다. 시속 3킬로로요."},{"who":"제국 병사","text":"그 속도면 제가 얼마든지 올라탈 수 있습니다."}],"stars":{"1":{"who":"아네트","text":"정지가 늦었습니다. 용광로 앞에서 병사 대기열이 생겼습니다."},"2":{"who":"아네트","text":"정지 성공. 병사 몇 명이 벨트 끝까지 갔다 오셨습니다."},"3":{"who":"아네트","text":"레버 정지 성공, 병사 이탈 0."}}},{"id":"F2-4","no":4,"title":"용광로 앞의 변명","boss":false,"before":[{"who":"아네트","text":"용광로 구역입니다. 기온 41도. 렌 중위님, 오늘도 몸이 떨리시나요?"},{"who":"렌","text":"떨리지 않는다. 열기에 땀이 났을 뿐이다."},{"who":"톰","text":"떨림이 아니고 땀이었군요. 저도 땀이 납니다. 담요 벗을게요."},{"who":"렌","text":"벗지 마라. 자네는 옷이 벗겨질 때까지 담요를 놓으면 안 된다."},{"who":"그레타","text":"의외로 배려가 있구만."},{"who":"제국 병사","text":"이 온도에선 우리 갑주가 열을 받아 돌진한다! 크하하!"},{"who":"클레어","text":"열 받은 갑주는 식혀 드리는 게 예의죠. 그레타, 냉각제 투척."}],"after":[{"who":"렌","text":"식은 건 갑주만이 아니다. 내 마음도 냉정해졌다."},{"who":"아네트","text":"체온 38.7도로 아직 높으십니다."},{"who":"렌","text":"체온은 마음과 무관하다."},{"who":"톰","text":"손 잡아 드릴까요?"},{"who":"렌","text":"…잡아라."}],"stars":{"1":{"who":"아네트","text":"냉각 불량. 용광로 근처 대기열이 과열되었습니다."},"2":{"who":"아네트","text":"냉각 양호. 용광로 앞 병사 일부가 열기에 만족하고 계십니다."},"3":{"who":"아네트","text":"냉각 완벽, 대원 체온 전원 정상(렌 중위 제외)."}}},{"id":"F2-5","no":5,"title":"폭주하는 드워프","boss":false,"before":[{"who":"아네트","text":"제국 공병 상사 이그니스가 증기 갑주를 입은 채 폭주 중입니다. 갑주 안에서 11일째 나오지 못했다는 보고가 있어요."},{"who":"이그니스","text":"(확성기) 내가 이 갑주를 만든 장본인이다! 이 안에서 내려갈 일은 없다!"},{"who":"그레타","text":"속이 많이 불편한 목소리구만."},{"who":"바르샤","text":"(망치로 갑주를 쾅) 불편하다."},{"who":"클레어","text":"공병 바르샤 씨가 동의하시는군요. 접근해서 갑주를 열어 보죠."},{"who":"이그니스","text":"열 필요 없다! 이 갑주는 열면 내 자존심이 새어 나온다!"},{"who":"아네트","text":"자존심 외에도 뭔가 새어 나올 것 같은데요."}],"after":[{"who":"바르샤","text":"(망치로 갑주를 쾅) 열었다."},{"who":"이그니스","text":"으윽, 후, 후우…… 11일이다. 11일 동안 안에 있었다."},{"who":"그레타","text":"속은 괜찮고?"},{"who":"이그니스","text":"속이라니 무슨 소리냐! …정확히 말하면 막혀 있다."},{"who":"클레어","text":"치료가 필요하겠군요. 다음 시간에 상담소로 모시겠습니다."}],"stars":{"1":{"who":"아네트","text":"개방이 늦어졌습니다. 갑주 내 환경이 위험해졌습니다."},"2":{"who":"아네트","text":"개방 성공. 상사님이 갑주 안에서 비명을 지르셨습니다."},"3":{"who":"아네트","text":"갑주 개방 성공, 이그니스 상사 의식 양호."}}},{"id":"F2-6","no":6,"title":"핑크 패들 찜질 + 대청소","boss":false,"before":[{"who":"아네트","text":"이그니스 상사의 폭주 원인을 확인했습니다. 11일 연속 근무, 진단명은 만성 변비입니다."},{"who":"클레어","text":"…폭주의 원인이 그것이었군요."},{"who":"그레타","text":"압력 밸브가 막혀서 성질이 터진 거구만. 드워프는 속이 막히면 성질도 막히는 법이야."},{"who":"바르샤","text":"(망치로 갑주를 쾅) 막혔다."},{"who":"이그니스","text":"(갑주 안에서 확성기로) 투항은 없다! 열하루 동안 쌓아 온 이 철의 의지로!!"},{"who":"클레어","text":"열하루 쌓인 것은 의지가 아닌 것 같습니다."},{"who":"제국 병사","text":"(방독면 착용) 상사님 곁에는 못 가겠습니다. 눈이 따갑고 코가 막혀서……"},{"who":"그레타","text":"기가 막히는 건 이쪽이구만. 코는 덤이고."},{"who":"아네트","text":"치료는 두 단계입니다. 1단계 「핑크 패들 찜질」로 장을 깨우고, 2단계 「대청소」로 마무리합니다."},{"who":"실비아","text":"아네트 씨. 예의 바르게 말씀드리겠습니다. 시연을 저에게 먼저 해 주세요. 두꺼운 쪽으로, 부탁드립니다."},{"who":"클레어","text":"정중하게 말씀하시니 거절하기가 어렵군요. 이그니스 상사 다음으로 하시죠."},{"who":"톰","text":"저도 순번표 받아도 됩니까?"},{"who":"아네트","text":"3번이세요."},{"who":"렌","text":"나는 필요 없다. …몇 번까지 나갔나."},{"who":"아네트","text":"4번입니다."},{"who":"렌","text":"…받겠다."}],"after":[{"who":"","kind":"stage","text":"(화면 밖: 짝—— 짝—— 쩌렁——)"},{"who":"이그니스","text":"으악! 아! 아아! …어? 어어? 뭔가 움직인다! 내 안에서 뭔가가 출발한다!"},{"who":"그레타","text":"출발이라니, 열차냐."},{"who":"아네트","text":"2단계 「대청소」 들어갑니다. 바르샤 공병님, 후미 밸브 개방 부탁드립니다."},{"who":"바르샤","text":"(망치로 밸브를 쾅) 열었다."},{"who":"","kind":"stage","text":"(화면 밖: 꾸르르르륵…… 뿌우우우웅——)"},{"who":"제국 병사","text":"(방독면 안에서) 눈물이 납니다…… 상사님의 11일이 한꺼번에…… (털썩)"},{"who":"이그니스","text":"…열하루 만이다. 눈물이 난다. 진짜 눈물이. 연방 만세다."},{"who":"그레타","text":"우는 건 개운해서가 맞는 거지?"},{"who":"이그니스","text":"개운해서도 맞고 패들이 좋아서도 맞다. 한 번만 더 해 줄 수 있나."},{"who":"아네트","text":"재방문 예약은 목요일에 잡아 놨습니다. 아침, 식후입니다."},{"who":"실비아","text":"자, 이제 제 차례입니다. (몸을 숙인다) 정중하게 부탁드립니다."},{"who":"","kind":"stage","text":"(화면 밖: 짝!)"},{"who":"실비아","text":"…감사합니다. 한 번 더 정중하게 부탁드립니다."},{"who":"클레어","text":"그 정중함은 어디서 배우신 겁니까."},{"who":"실비아","text":"가정교육입니다. 원하는 것은 예의 바르게 요청하라고 배웠습니다."}],"stars":{"1":{"who":"아네트","text":"배출이 늦어서 현장이 가득 찼습니다. 다음에는 방독면을 두 배 준비하겠습니다."},"2":{"who":"아네트","text":"배출 양호. 병사 몇 분이 환기 전에 쓰러지셔서 보상 처리가 필요합니다."},"3":{"who":"아네트","text":"완벽한 배출입니다. 환자 만족도 최상, 방독면 반납률 100%, 재방문 예약 포함."}}},{"id":"F2-7","no":7,"title":"족쇄 점검 시간","boss":false,"before":[{"who":"아네트","text":"월례 족쇄 점검의 날입니다. 톰 병장님, 렌 중위님, 앞으로."},{"who":"톰","text":"네, 족쇄가 조금 헐거운 것 같습니다. 더 조여 주시면 안심이 되겠는데요."},{"who":"클레어","text":"병장님이 먼저 조여 달라고 하신 건 처음입니다."},{"who":"톰","text":"헐거우면 길을 잃는 기분이라서요. 딸이 어릴 때도 손을 꽉 잡아야 안심했거든요."},{"who":"렌","text":"나는 헐거운 게 편하다. …아니, 헐거운 건 효율이 낮다."},{"who":"아네트","text":"렌 중위님, 장력 82%입니다. 규정은 90%."},{"who":"렌","text":"(뒤로 물러서며) 필요 없다! …해 주십시오."}],"after":[{"who":"아네트","text":"조정 완료. 톰 병장님 92%, 렌 중위님 92%."},{"who":"렌","text":"장력이 92%…… 이 수치는 전술적으로 의미가 있나?"},{"who":"아네트","text":"있습니다. 3미터 안에서만 숨이 편하다는 의미입니다."},{"who":"렌","text":"…그건 의미가 있군."}],"stars":{"1":{"who":"아네트","text":"점검이 길어졌습니다. 조임 정도에 대한 의견 차가 있었습니다."},"2":{"who":"아네트","text":"점검 합격. 렌 중위님이 재조정을 요청하셨습니다."},"3":{"who":"아네트","text":"점검 전원 합격. 장력 92%로 통일."}}},{"id":"F2-8","no":8,"title":"장인의 자존심","boss":false,"before":[{"who":"그레타","text":"이그니스. 같은 장인 계보에서 컸다는 소문은 사실이구만."},{"who":"이그니스","text":"그레타 영감의 제자가 연방에 있다더니 너였군! 그 망치질은 여전히 둔하냐!"},{"who":"그레타","text":"둔한지 안 둔한지는 두들겨 보면 알지."},{"who":"바르샤","text":"(망치로 바닥을 쾅) 대결이다."},{"who":"클레어","text":"대결이라고요. 심판은 아네트입니다."},{"who":"아네트","text":"평가 기준은 「누구의 망치질이 더 듣기 좋은가」입니다."},{"who":"실비아","text":"소리 평가라면 제가 귀가 밝습니다. 엄정하게 듣겠습니다."}],"after":[{"who":"이그니스","text":"졌다…… 저 망치의 박자가 너무 정확해."},{"who":"그레타","text":"자네 박자는 마음이 급해서 그런 거야. 한 번 맞아 보게."},{"who":"이그니스","text":"맞다니? 내가 장인인데 감히!"},{"who":"그레타","text":"장인끼리의 교정이야. 가볍게 다섯 번."},{"who":"이그니스","text":"…다섯 번이면 되겠나."}],"stars":{"1":{"who":"아네트","text":"박자 불일치. 두 분의 자존심 마찰로 현장이 소란스러워졌습니다."},"2":{"who":"아네트","text":"박자 양호, 이그니스 상사의 불평이 접수되었습니다."},"3":{"who":"아네트","text":"망치 박자 완벽 일치, 장인 존중도 최상."}}},{"id":"F2-9","no":9,"title":"전야의 냉각 작업","boss":false,"before":[{"who":"아네트","text":"내일은 보스전입니다. 오늘은 대원 전원 냉각 작업을 하겠습니다. 순서대로 번호표를."},{"who":"톰","text":"저는 5번입니다. 담요를 꼭 안고 기다리겠습니다."},{"who":"렌","text":"나는 7번이다. …왜 7번이 이렇게 앞이지?"},{"who":"아네트","text":"대기 중 선호도가 높아서 앞당겨졌습니다."},{"who":"렌","text":"나는 선호도가 높지 않다."},{"who":"아네트","text":"차트에는 「매우 높음」이라고 적혀 있습니다."},{"who":"렌","text":"차트를 고쳐라."}],"after":[{"who":"이그니스","text":"(멀리서) 나도 번호표 받을 수 있나?"},{"who":"아네트","text":"이그니스 상사님은 재방문 건이라 우선권이 있습니다."},{"who":"바르샤","text":"(망치로 접수대를 쾅) 좋다."},{"who":"클레어","text":"모두 좋은 밤 되세요. 내일은 큰 타이탄이 옵니다."}],"stars":{"1":{"who":"아네트","text":"대기열이 과열되었습니다. 차트 정리가 필요합니다."},"2":{"who":"아네트","text":"냉각 작업 양호. 일부 대원 순서가 뒤바뀌었습니다."},"3":{"who":"아네트","text":"냉각 작업 전원 완료. 대기 시간 평균 6분."}}},{"id":"F2-10","no":10,"title":"브레이저 타이탄","boss":true,"before":[{"who":"클레어","text":"이그니스 상사의 마지막 기체 「브레이저 타이탄」입니다. 높이 15미터, 용광로를 가슴에 탑재했네요."},{"who":"이그니스","text":"(확성기) 내 속은 이제 뻥 뚫렸지만 자존심은 아직 막혀 있다! 이 타이탄으로 마지막 전투를 하겠다!"},{"who":"그레타","text":"막힌 게 자존심이면 두들겨서 뚫어야지."},{"who":"바르샤","text":"(망치로 바닥을 쾅) 부수자."},{"who":"아네트","text":"제가 지원하겠습니다. 1단계 패들, 2단계 대청소 준비 완료."},{"who":"이그니스","text":"대청소는 이제 필요 없다! 다만 패들은 한 번 더…… 아니, 전투 중에는 안 된다!"}],"after":[{"who":"이그니스","text":"졌다. 완전히 졌다. 속도 시원하고 마음도 시원하다."},{"who":"그레타","text":"항복이야?"},{"who":"이그니스","text":"항복이다. 다음 주 목요일 아침 식후에 예약했다. 위치는 알고 있다."},{"who":"클레어","text":"2장 종료입니다. 공방이 연방의 소유가 되었군요."},{"who":"렌","text":"…이그니스 상사님 번호가 제 앞이었나."}],"stars":{"1":{"who":"아네트","text":"타이탄이 반파되었습니다. 상사님은 갑주 안에서 아직 버티고 계십니다."},"2":{"who":"아네트","text":"타이탄 파괴. 상사님은 갑주를 벗고 자진 이송되었습니다."},"3":{"who":"아네트","text":"타이탄 파괴. 이그니스 상사 포획, 재방문 확정."}}}]},"F3":{"chapter":"F3","title":"사막 통상로","line":"female","episodes":[{"id":"F3-1","no":1,"title":"통상로 개통식","boss":false,"before":[{"who":"클레어","text":"사막 통상로가 오늘부터 연방 관할입니다. 개통식을 겸한 전투가 되겠군요."},{"who":"톰","text":"아침 정화 체조 끝났습니다. 초커는 제가 먼저 채웠어요. 한 번에 딱 맞네요."},{"who":"아네트","text":"병장님, 스스로 채우셨군요. 칭찬 스티커를 드리겠습니다."},{"who":"톰","text":"감사합니다. 딸에게 자랑할게요."},{"who":"렌","text":"나는 아침 체조를 하지 않았다. …체조가 아니라 작전 전 준비였다."},{"who":"그레타","text":"준비하는 표정이 설레는 얼굴이구만."},{"who":"제국 병사","text":"개통식이라니, 우린 초대 못 받았다!"},{"who":"클레어","text":"초대장은 포획 후 발송합니다."}],"after":[{"who":"아네트","text":"개통 완료. 병사 28명 포획, 초대장 발송."},{"who":"제국 병사","text":"초대장이 도착했다! 이건 상담소 예약권이다!"},{"who":"톰","text":"습관이 되니 이런 장면도 자연스럽네요."},{"who":"클레어","text":"루틴이 서면 전쟁도 일상이 됩니다."}],"stars":{"1":{"who":"아네트","text":"개통이 지연되었습니다. 의전 담당이 부족했습니다."},"2":{"who":"아네트","text":"개통 성공. 초대장 일부가 사막 바람에 날아갔습니다."},"3":{"who":"아네트","text":"개통식 완벽 진행, 방문객 만족도 최상."}}},{"id":"F3-2","no":2,"title":"낙타 상단의 짐 검수","boss":false,"before":[{"who":"아네트","text":"제국 보급 낙타대입니다. 짐 목록은 「모래 대비 식량」입니다."},{"who":"그레타","text":"식량 치고는 짐이 덜컥거리는 소리가 수상하구만."},{"who":"제국 병사","text":"식량이다! 정말이다! 안에 든 건 가죽 끈, 방울 달린 재갈, 그리고 말랑한 몽둥이다!"},{"who":"클레어","text":"그것은 식량이 아닌 것으로 압니다."},{"who":"제국 병사","text":"사막은 길고 외롭다. 우리도 밤에는 놀아야 한다."},{"who":"실비아","text":"정중하게 말씀드립니다. 말랑한 몽둥이의 탄성 검수를 제가 맡겠습니다."},{"who":"렌","text":"그건 군수품이다. 검수는 장교가 해야 한다."},{"who":"그레타","text":"중위가 이미 군수품 포장을 풀고 있구만."}],"after":[{"who":"아네트","text":"밀수품 목록 정리. 재갈 12, 가죽 끈 40, 말랑한 몽둥이 7."},{"who":"렌","text":"몽둥이는 내가 보관하겠다. 군 기밀이다."},{"who":"톰","text":"렌 중위님, 방금 하나 소매에 넣으셨습니다."},{"who":"렌","text":"…보관이다."}],"stars":{"1":{"who":"아네트","text":"일부 물품이 모래 속에 묻혔습니다. 채굴 인력이 필요합니다."},"2":{"who":"아네트","text":"압수 양호. 일부 물품이 대원 소매로 이동했습니다."},"3":{"who":"아네트","text":"밀수품 전량 압수, 압수 목록 정리 완료."}}},{"id":"F3-3","no":3,"title":"자하라의 꼬리 감기","boss":false,"before":[{"who":"아네트","text":"제국 전차 앞에 사막 연금 길드 객원 자하라 씨가 서 있습니다. 꼬리가 길어요."},{"who":"자하라","text":"안녕하세요, 연방 여러분. 제국 의뢰로 이 전차를 지켜야 해서요. 꼬리 감기 1회 요금은 금화 3닢입니다."},{"who":"그레타","text":"전차를 꼬리로 막는다고? 그게 되겠나."},{"who":"자하라","text":"(꼬리를 휘감아 포신을 조인다) 되는데요. 이래 봬도 조임 압력은 6기압입니다."},{"who":"클레어","text":"대단한 조임이군요. 예의상 홍차를 한 잔 권해도 될까요?"},{"who":"자하라","text":"홍차 요금은 별도입니다."},{"who":"실비아","text":"정중하게 평가하겠습니다. 감는 각도가 훌륭하십니다."}],"after":[{"who":"자하라","text":"이번엔 졌네요. 하지만 저는 포획되지 않습니다. 계약 해지 조항을 읽어 봤는데 저는 객원이라서요."},{"who":"아네트","text":"객원이시면 상담소 이용은 자유입니다. 재방문 권유서만 드리겠습니다."},{"who":"자하라","text":"권유서는 무료인가요?"},{"who":"아네트","text":"무료입니다."},{"who":"자하라","text":"…가져가겠습니다. 소장용으로."}],"stars":{"1":{"who":"아네트","text":"전차가 꼬리에 감겨 아직 못 움직입니다. 원인 분석 중."},"2":{"who":"아네트","text":"전차 정지. 자하라 씨는 요금 청구서를 두고 갔습니다."},"3":{"who":"아네트","text":"전차 정지, 자하라 씨 재방문 권유서 수령."}}},{"id":"F3-4","no":4,"title":"늑대 수인 카이단","boss":false,"before":[{"who":"아네트","text":"선두에서 늑대 수인이 돌진해 옵니다. 이름은 카이단, 제국 최강의 마초라는 소문입니다."},{"who":"카이단","text":"크아악! 연방의 고상한 암컷들아! 오늘은 내 이빨로 문장을 새겨 주마!"},{"who":"그레타","text":"전부 조준하는 쪽이 실비아구만."},{"who":"카이단","text":"저기 단아한 암컷은 내가 먼저 물겠다!"},{"who":"실비아","text":"정중하게 사양합니다."},{"who":"아네트","text":"카이단 씨, 저쪽으로 오세요. 초커를 채워 드리겠습니다."},{"who":"카이단","text":"초커? 그따위 목줄에 내가 굴복할 것 같으냐! 나는 사냥개가 아니라 늑대다!"}],"after":[{"who":"","kind":"stage","text":"(화면 밖: 철컥)"},{"who":"카이단","text":"이게 뭐야, 목에 뭔가 걸렸다. 으르릉…… 이거 뭐지, 뭔가 편한데."},{"who":"아네트","text":"카이단 씨 합류입니다. 정화방 일정은 다음 시간으로 잡겠습니다."},{"who":"카이단","text":"정화방은 안 간다! 내가 어디를 가는지는 내가 정한다!"},{"who":"클레어","text":"규정은 모두에게 동일합니다."},{"who":"카이단","text":"(꼬리가 한 번 흔들린다) …꼬리는 안 흔들었다."}],"stars":{"1":{"who":"아네트","text":"합류했으나 도주를 시도 중입니다. 족쇄 3미터 규정이 작동합니다."},"2":{"who":"아네트","text":"합류 완료. 정화방 거부 의사 표명 중."},"3":{"who":"아네트","text":"카이단 씨 합류. 초커 착용감 만족도, 꼬리 반응 우수."}}},{"id":"F3-5","no":5,"title":"깃털 간지럼의 사전 준비","boss":false,"before":[{"who":"아네트","text":"카이단 씨의 정화방 입실 전 사전 준비 단계입니다. 깃털 부위 확인."},{"who":"카이단","text":"깃털이라니 무슨 소리냐! 내 털은 늑대 털이다!"},{"who":"아네트","text":"이쪽 깃털은 하피 상단에서 구입한 최고급입니다. 간지럼 감도 상위 5%."},{"who":"카이단","text":"크하하…… 아, 아, 으하하하하!! 거기는 안 된다!! 거긴 안 돼!!"},{"who":"그레타","text":"늑대가 이렇게 크게 웃을 줄은 몰랐구만."},{"who":"카이단","text":"웃는 게 아니다! 비명이다! 크하핫!!"},{"who":"실비아","text":"비명이라 하기에는 입꼬리가 올라가 있는데요."}],"after":[{"who":"아네트","text":"사전 준비 완료. 간지럼 내성 0%."},{"who":"카이단","text":"내성이 0이라고…… 그건 전술적으로 위험하다."},{"who":"렌","text":"자네도 내성이 없나. 나와 같은 전술적 약점이군."},{"who":"카이단","text":"같은 약점이라니, 불쾌하다. …하지만 동지애가 느껴진다."}],"stars":{"1":{"who":"아네트","text":"준비가 지연되었습니다. 깃털이 바람에 날아갔습니다."},"2":{"who":"아네트","text":"준비 양호. 카이단 씨가 중간에 도망치려 했습니다."},"3":{"who":"아네트","text":"간지럼 사전 준비 완벽, 웃음소리 120데시벨."}}},{"id":"F3-6","no":6,"title":"정화방 탈출 작전","boss":false,"before":[{"who":"아네트","text":"카이단 씨가 정화방 입실 직전에 도주했습니다. 변장 중입니다."},{"who":"카이단","text":"(커다란 가발 쓰고) 저는 평범한 낙타입니다! 낙타가 말을 하는 건 사막에서 흔한 일입니다!"},{"who":"그레타","text":"낙타 귀가 늑대 귀구만."},{"who":"카이단","text":"아니다. 이건 낙타용 장식이다."},{"who":"톰","text":"늑대님, 제 담요 덮어 드릴까요? 낙타도 추울 땐 담요를 쓰거든요."},{"who":"카이단","text":"담요는…… 따뜻하다. 아니다, 나는 도망 중이다."},{"who":"클레어","text":"족쇄 3미터 규정이 작동합니다. 아네트."}],"after":[{"who":"카이단","text":"땅굴을 팠는데 3미터 지점에서 당겨졌다!"},{"who":"아네트","text":"규정입니다."},{"who":"카이단","text":"그럼 낙타 위장도, 땅굴도, 가발도 소용없단 말인가!"},{"who":"클레어","text":"소용은 있었습니다. 즐겁게 구경했거든요."},{"who":"카이단","text":"…정화방은 안 간다고 했다."}],"stars":{"1":{"who":"아네트","text":"저지 지연. 카이단 씨가 사막 한가운데서 길을 잃으셨습니다."},"2":{"who":"아네트","text":"저지 4회. 1회는 가발만 놓고 도주했습니다."},"3":{"who":"아네트","text":"탈출 시도 5회 모두 저지, 관람 만족도 최상."}}},{"id":"F3-7","no":7,"title":"다녀오더니","boss":false,"before":[{"who":"아네트","text":"카이단 씨가 정화방 입실을 마쳤습니다. 소요 시간 18분."},{"who":"그레타","text":"18분 만에 나왔구만. 어디 보자, 표정이 어때."},{"who":"카이단","text":"(문이 열리고) …주인님. 산책 가요?"},{"who":"그레타","text":"이게 누구냐."},{"who":"카이단","text":"(꼬리가 쉬지 않고 흔들린다) 저는 카이단입니다! 주인님, 초커 잘 어울리죠? 오늘도 저 먼저 불러 주세요!"},{"who":"클레어","text":"정화 효과가 뚜렷하군요."},{"who":"렌","text":"이럴 수가. 최강의 마초가 불과 18분 만에."},{"who":"카이단","text":"렌 중위님, 같이 가요! 정화방 진짜 좋아요!"},{"who":"렌","text":"…나는 아직 안 간다. 몸이 먼저 갈 뿐이지 마음은 아직이다."}],"after":[{"who":"카이단","text":"주인님, 칭찬해 주세요! 오늘도 적 열 명 잡았어요!"},{"who":"클레어","text":"잘하셨어요, 카이단 씨. (머리 쓰다듬)"},{"who":"카이단","text":"크응, 크응…… (꼬리가 땅에 닿을 정도로 흔든다)"},{"who":"그레타","text":"원래 이런 놈이었던 것 같구만."},{"who":"톰","text":"습관이 되면 사람이 편해지는군요."}],"stars":{"1":{"who":"아네트","text":"모드 불안정. 정화방 재방문 권유서를 발송합니다."},"2":{"who":"아네트","text":"멍뭉이 모드 80%. 가끔 마초 모드가 복귀합니다."},"3":{"who":"아네트","text":"카이단 씨 멍뭉이 모드 100%, 꼬리 진동 120회/분."}}},{"id":"F3-8","no":8,"title":"렌의 신념","boss":false,"before":[{"who":"아네트","text":"렌 중위님, 오늘 정화방 예약이 잡혀 있습니다."},{"who":"렌","text":"나는 굴복하지 않았다. 몸이 먼저 갔을 뿐이다. 이 점은 반드시 기록해 두길 바란다."},{"who":"아네트","text":"기록했습니다. 「몸이 먼저 감, 마음은 저항 중」."},{"who":"카이단","text":"렌 중위님, 마음도 같이 가요! 저는 마음도 같이 갔어요!"},{"who":"렌","text":"마음은 군인의 마지막 보루다. 쉽게 내줄 수 없다."},{"who":"톰","text":"보루가 있으신 분은 대단하십니다. 저는 첫날에 내줬습니다."},{"who":"그레타","text":"순번표는 7번이구만."}],"after":[{"who":"렌","text":"다녀왔다. …이상 없다. 아무 일도 없었다."},{"who":"아네트","text":"체온 39도, 심박 120, 표정 이완 상태입니다."},{"who":"렌","text":"그건 군인의 피로다."},{"who":"카이단","text":"렌 중위님 얼굴이 빨개요! 같이 산책해요!"},{"who":"렌","text":"산책은…… 한 바퀴만이다."}],"stars":{"1":{"who":"아네트","text":"신념에 균열 발생. 다음 예약을 앞당기겠습니다."},"2":{"who":"아네트","text":"신념 유지. 퇴실 후 몸이 더 자주 떨립니다."},"3":{"who":"아네트","text":"렌 중위님 신념 유지(표면), 몸 반응 정직."}}},{"id":"F3-9","no":9,"title":"모래폭풍 전야","boss":false,"before":[{"who":"클레어","text":"내일은 장갑 열차 군단과 맞섭니다. 오늘 밤 모래폭풍이 예보되었네요."},{"who":"톰","text":"담요가 5장입니다. 대원 수대로 나눠 드릴게요."},{"who":"카이단","text":"주인님 옆에 누울래요! 늑대는 원래 무리 지어 자니까요!"},{"who":"렌","text":"나는 텐트 가장자리에서 자겠다. …가장자리는 바람이 불어서 춥다."},{"who":"그레타","text":"중위 옆자리를 비워 뒀구만."},{"who":"렌","text":"비워 둔 건 배려로 받아들이겠다."}],"after":[{"who":"아네트","text":"폭풍 속에서도 대원 전원 안전합니다."},{"who":"톰","text":"모래 소리가 파도 같아요. 딸이 파도를 좋아했거든요."},{"who":"카이단","text":"크응…… (잠든다)"},{"who":"클레어","text":"좋은 밤입니다. 내일은 열차입니다."}],"stars":{"1":{"who":"아네트","text":"모래폭풍으로 텐트 일부가 날아갔습니다."},"2":{"who":"아네트","text":"야영 양호. 담요 몇 장이 모래에 파묻혔습니다."},"3":{"who":"아네트","text":"야영 만족도 최상, 담요 배분 오차 0."}}},{"id":"F3-10","no":10,"title":"제국 장갑 열차 군단","boss":true,"before":[{"who":"클레어","text":"사막 한가운데로 달려오는 제국 장갑 열차 군단. 10량 편성입니다."},{"who":"제국 기관사","text":"우리 열차는 연료도 속도도 최고다! 브레이크는 고장 났다!"},{"who":"그레타","text":"브레이크 고장 난 열차로 어쩌겠다는 거구만."},{"who":"제국 기관사","text":"우리가 목적지에 도착하면 정화 상담소를 열어 줄 거라 들었다!"},{"who":"아네트","text":"소문이 빠르네요."},{"who":"카이단","text":"주인님, 열차 쫓아가도 돼요? 쫓아가서 물어 오고 싶어요!"},{"who":"렌","text":"허가한다. 아니, 허가를 구한다."}],"after":[{"who":"제국 기관사","text":"졌다. 하지만 브레이크가 없어서 계속 달려간다."},{"who":"그레타","text":"그걸 누가 멈추나."},{"who":"카이단","text":"제가 갈게요! (달려간다)"},{"who":"클레어","text":"3장 종료입니다. 통상로가 연방 소유가 되었군요. 카이단 씨, 반드시 돌아오세요."},{"who":"톰","text":"늑대가 열차를 잡아 오는 장면은 처음 봅니다."}],"stars":{"1":{"who":"아네트","text":"열차가 사막 끝까지 달렸습니다. 회수 작업을 시작합니다."},"2":{"who":"아네트","text":"열차 정지. 카이단 씨가 모래 먼지를 뒤집어쓰고 돌아오셨습니다."},"3":{"who":"아네트","text":"열차 군단 정지, 카이단 씨 무사 귀환, 꼬리 진동 최대."}}}]},"F4":{"chapter":"F4","title":"야간 점호","line":"female","episodes":[{"id":"F4-1","no":1,"title":"야간 점호의 예약 전쟁","boss":false,"before":[{"who":"아네트","text":"도심에 밤이 내렸습니다. 야간 점호를 시작합니다. 톰 병장님, 렌 중위님, 카이단 씨, 번호 순서대로 보고하세요."},{"who":"톰","text":"1번 톰입니다. 오늘 정화방 예약, 이미 걸어 뒀습니다."},{"who":"카이단","text":"2번 카이단! 저도 걸었어요! 3번 렌 중위님은 안 걸었는데 제가 대신 걸어 놨어요!"},{"who":"렌","text":"누가 내 번호를 걸었나. …취소는 하지 않겠다."},{"who":"그레타","text":"예약이 이미 이틀치 차 있구만."},{"who":"클레어","text":"수요가 많다는 건 서비스가 좋다는 증거죠."},{"who":"제국 병사","text":"우리도 예약하고 싶다! 줄이 어디냐!"}],"after":[{"who":"아네트","text":"오늘 포획 22명. 예약 대기 78명. 인력이 부족합니다."},{"who":"톰","text":"저희가 번호표를 나눠 줄까요? 봉사 활동이라고 생각하고요."},{"who":"렌","text":"번호표 배부는 장교의 임무다. 내가 맡겠다. (자기 번호표를 맨 위에 넣는다)"},{"who":"카이단","text":"렌 중위님이 새치기하셨어요!"},{"who":"렌","text":"이건 전술적 우선순위다."}],"stars":{"1":{"who":"아네트","text":"예약 대기 혼잡. 상담소 앞 줄이 골목 하나를 막았습니다."},"2":{"who":"아네트","text":"점호 양호. 새치기 1건 발생."},"3":{"who":"아네트","text":"점호 완벽, 예약 정리 100%, 새치기 적발 0."}}},{"id":"F4-2","no":2,"title":"가로등 아래의 방문 판매","boss":false,"before":[{"who":"아네트","text":"제국 야간 노점상이 가로등 아래 도구를 팔고 있습니다. 상호는 「심야 철물점」."},{"who":"노점상","text":"어서 오세요! 오늘의 추천은 쫀득 채찍과 귀여운 방울 재갈입니다!"},{"who":"그레타","text":"장사가 자연스러워서 오히려 말릴 수가 없구만."},{"who":"실비아","text":"정중하게 질문합니다. 채찍의 손잡이 소재는 무엇인가요."},{"who":"노점상","text":"사막 코끼리 가죽입니다. 손에 착 감깁니다."},{"who":"실비아","text":"구매하겠습니다. 영수증 부탁드립니다."},{"who":"클레어","text":"실비아, 오늘은 전투입니다."},{"who":"실비아","text":"전투 후 구매로 하겠습니다. 예약 부탁드립니다."}],"after":[{"who":"노점상","text":"포획이라니, 제 가게는 어떻게 되는 겁니까?"},{"who":"아네트","text":"상담소 안에 입점하셔도 됩니다. 임대료는 월 정산입니다."},{"who":"노점상","text":"입점이라니, 영광입니다."},{"who":"클레어","text":"연방과 제국의 첫 합작 가게가 되겠군요."}],"stars":{"1":{"who":"아네트","text":"점포 철수 중 일부 상품이 분실되었습니다."},"2":{"who":"아네트","text":"입점 확정. 방울 재갈 재고 일부 손실."},"3":{"who":"아네트","text":"노점상 입점 확정, 쫀득 채찍 재고 확보."}}},{"id":"F4-3","no":3,"title":"노예 부대의 첫 전선","boss":false,"before":[{"who":"클레어","text":"오늘은 노예 부대가 처음으로 최전선에 섭니다. 톰, 렌, 카이단."},{"who":"톰","text":"알겠습니다. 담요 대신 방패를 들고 가겠습니다."},{"who":"카이단","text":"주인님 옆이면 어디든 갈게요!"},{"who":"아네트","text":"3미터 규정이 중요합니다. 주인에게서 3미터 이상 떨어지면 당겨집니다."},{"who":"렌","text":"그럼 세 명이 서로 다른 방향으로 달리면 어떻게 되나."},{"who":"아네트","text":"줄이 엉켜 서로 모이게 됩니다."},{"who":"렌","text":"그건 서로 부둥켜안게 된다는 뜻이다."},{"who":"그레타","text":"부둥켜안는 전술이구만."}],"after":[{"who":"카이단","text":"렌 중위님, 우리 꼬였어요! 엉켜서 따뜻해요!"},{"who":"렌","text":"이건 전술적 근접전이다. …풀어 달라고는 안 하겠다."},{"who":"톰","text":"저도 같이 엉켜 있겠습니다. 서로 담요가 되니까요."},{"who":"아네트","text":"줄 정리는 5분 걸립니다. 그 사이 쉬세요."}],"stars":{"1":{"who":"아네트","text":"줄 엉킴이 과도해 이동이 지연되었습니다."},"2":{"who":"아네트","text":"전선 완수. 엉킴 해소에 7분이 걸렸습니다."},"3":{"who":"아네트","text":"첫 전선 완수, 줄 엉킴 만족도 최상."}}},{"id":"F4-4","no":4,"title":"옥상 정화 파티","boss":false,"before":[{"who":"클레어","text":"도심 옥상에 제국 병사들이 집결했습니다. 구경꾼도 몰렸군요."},{"who":"연방 시민","text":"오늘도 정화 구경 왔어요! 간식 팔아요!"},{"who":"그레타","text":"전투 구경이 관광 상품이 됐구만."},{"who":"제국 병사","text":"우리를 구경거리로 삼는 건가!"},{"who":"연방 시민","text":"아니에요, 응원하는 거예요! 힘내세요!"},{"who":"제국 병사","text":"…응원이라니, 고맙다."},{"who":"아네트","text":"포획 후 포토 존도 마련했습니다."}],"after":[{"who":"연방 시민","text":"포획된 병사님과 사진 찍어도 되나요?"},{"who":"제국 병사","text":"얼마든지다! 초커가 보이게 찍어 달라!"},{"who":"톰","text":"인기가 있네요. 저도 같이 찍을까요."},{"who":"렌","text":"나는 안 찍는다. …찍으려면 측면으로."}],"stars":{"1":{"who":"아네트","text":"시민들이 위험 구역에 접근해 통제가 필요했습니다."},"2":{"who":"아네트","text":"제압 성공. 간식 재고가 소진되었습니다."},"3":{"who":"아네트","text":"옥상 제압, 시민 응원 120%."}}},{"id":"F4-5","no":5,"title":"로나의 조련","boss":false,"before":[{"who":"아네트","text":"제국 용병 돌격대장 그로크가 돌진 중입니다. 오크, 키 2.4미터."},{"who":"그로크","text":"크하하! 연방 암컷들아, 사이즈에 놀라 도망쳐라!"},{"who":"로나","text":"(연방 장교, 낮은 목소리) 저는 도망치지 않습니다. 사이즈는 측정이 끝났습니다."},{"who":"그로크","text":"측정이라니, 뭐냐!"},{"who":"로나","text":"어제 방문하셨을 때 차트에 적었습니다. 「가장 큰 부분은 자신감」."},{"who":"그로크","text":"으윽, 그걸 어떻게!"}],"after":[{"who":"로나","text":"조련 시작합니다. 그로크 대장, 무릎."},{"who":"그로크","text":"내가 왜 무릎을 꿇어야 하나! 나는 오크 대장이다!"},{"who":"로나","text":"무릎."},{"who":"그로크","text":"(털썩) …꿇었다."},{"who":"로나","text":"잘했어요. 이제 그 입으로 한 말은 책임져야죠."},{"who":"그로크","text":"책임지겠습니다."},{"who":"클레어","text":"합류를 환영합니다, 그로크 대장님."}],"stars":{"1":{"who":"아네트","text":"합류했으나 여전히 목소리가 큽니다. 훈련이 필요합니다."},"2":{"who":"아네트","text":"합류 완료. 무릎 꿇기까지 3초 지연되었습니다."},"3":{"who":"아네트","text":"그로크 대장님 합류. 로나 교관의 조련 성적 최우수."}}},{"id":"F4-6","no":6,"title":"더 매도해 달라","boss":false,"before":[{"who":"로나","text":"그로크 대장, 오늘 전선에서 불필요한 소리를 질렀죠."},{"who":"그로크","text":"죄송합니다, 로나 교관님. 한 번 더 매도해 주실 수 있습니까?"},{"who":"로나","text":"매도라니, 원래 내 업무가 아닙니다."},{"who":"그로크","text":"더 매도해 주십시오. 오늘 전투 평가도 낮게 적어 주십시오. 그래야 의욕이 생깁니다."},{"who":"그레타","text":"오크 대장이 점수를 깎아 달라고 부탁하는 건 처음 보는구만."},{"who":"톰","text":"저도 칭찬받는 쪽이 좋은데, 사람마다 다르네요."},{"who":"카이단","text":"저는 칭찬이 좋아요!"},{"who":"렌","text":"나는…… 둘 다 아닌 척하겠다."}],"after":[{"who":"로나","text":"평가는 「하」입니다. 반성문 5장."},{"who":"그로크","text":"감사합니다! 반성문은 6장 쓰겠습니다!"},{"who":"로나","text":"규정은 5장입니다."},{"who":"그로크","text":"6장째는 제 선물입니다. 받아 주십시오."},{"who":"로나","text":"…접수는 하겠습니다."}],"stars":{"1":{"who":"아네트","text":"평가가 상향되어 그로크 대장님이 낙담했습니다."},"2":{"who":"아네트","text":"평가 「하」, 반성문 6장. 로나 교관의 한숨이 기록되었습니다."},"3":{"who":"아네트","text":"매도 평가 「하」, 그로크 대장님 만족도 최상."}}},{"id":"F4-7","no":7,"title":"하피 편대의 핑크 가스","boss":false,"before":[{"who":"아네트","text":"연방 하피 편대 벨루가가 상공에서 핑크 가스탄을 투척합니다."},{"who":"벨루가","text":"안녕! 오늘 가스는 딸기 향이야! 마시면 기분이 좋아져!"},{"who":"클레어","text":"연방 소속 비행대가 아군에게 뿌리면 안 됩니다."},{"who":"벨루가","text":"아, 맞다. 방향 틀렸네!"},{"who":"그레타","text":"가스가 제국 쪽으로 가는구만."},{"who":"제국 병사","text":"딸기 향이다! 아, 기분이 이상하다!"},{"who":"실비아","text":"정중하게 말씀드립니다. 저도 조금 마셔도 되겠습니까."},{"who":"클레어","text":"안 됩니다."}],"after":[{"who":"벨루가","text":"성공이다! 제국이 다 흐물흐물해졌어!"},{"who":"아네트","text":"가스 농도 3%. 아군 피해 0. 그러나 도시 전체에 딸기 향이 퍼졌습니다."},{"who":"연방 시민","text":"오늘 밤은 향이 좋네요!"},{"who":"클레어","text":"벨루가, 다음엔 향을 바꿔 주세요. 포도로."}],"stars":{"1":{"who":"아네트","text":"가스 농도 과다. 환기 작업이 필요합니다."},"2":{"who":"아네트","text":"성공. 일부 시민이 지나치게 기분이 좋아졌습니다."},"3":{"who":"아네트","text":"가스 투척 성공, 도시 만족도 최상."}}},{"id":"F4-8","no":8,"title":"가스 후유증","boss":false,"before":[{"who":"아네트","text":"어제의 가스 후유증으로 대원 일부가 업무에 집중하지 못합니다."},{"who":"톰","text":"딸기 향이 아직 남아서 기분이 좋습니다. 일해야 하는데 담요에 눕고 싶어요."},{"who":"카이단","text":"주인님, 꼬리가 안 멈춰요!"},{"who":"렌","text":"나는 정상이다. 다만 시야가 약간 분홍색이다."},{"who":"그레타","text":"중위는 전부터 분홍색이었구만."},{"who":"클레어","text":"오늘은 가벼운 전투만 하겠습니다."},{"who":"제국 병사","text":"우리도 분홍색이다! 전선이 흔들린다!"}],"after":[{"who":"아네트","text":"전투 종료. 쌍방 전투력 40% 저하."},{"who":"그로크","text":"로나 교관님, 오늘 성적은 몇 점입니까?"},{"who":"로나","text":"「하」입니다."},{"who":"그로크","text":"감사합니다!"},{"who":"클레어","text":"전쟁인지 야유회인지 기록하기 어렵군요."}],"stars":{"1":{"who":"아네트","text":"분홍 시야로 인해 아군 오인 사격이 있었습니다."},"2":{"who":"아네트","text":"승리. 일부 대원이 잠들었습니다."},"3":{"who":"아네트","text":"후유증 속 승리, 야유회 만족도 최상."}}},{"id":"F4-9","no":9,"title":"전야의 족쇄 점검","boss":false,"before":[{"who":"아네트","text":"내일은 보스전입니다. 족쇄와 초커 점검 시간. 톰, 렌, 카이단, 그로크 순으로."},{"who":"톰","text":"94%입니다. 오늘은 한 단계 더 조여 주세요."},{"who":"카이단","text":"저는 100%로 해 주세요! 꽉 조여야 마음이 놓여요!"},{"who":"그로크","text":"저는 120%로 부탁합니다."},{"who":"아네트","text":"규정 최대치는 100%입니다."},{"who":"그로크","text":"규정을 위반해서 처벌받고 싶습니다."},{"who":"렌","text":"나는 규정대로 92%로 충분하다. …95%로 해 줘도 규정 위반은 아니다."}],"after":[{"who":"아네트","text":"점검 완료. 전원 평균 98%."},{"who":"톰","text":"푹 잘 수 있겠네요. 따뜻합니다."},{"who":"렌","text":"나도 따뜻하다. 이것은 군인의 사기다."},{"who":"클레어","text":"내일은 야간 폭격 비공정입니다. 모두 좋은 밤."}],"stars":{"1":{"who":"아네트","text":"점검이 길어졌습니다. 조임 정도에 대한 협상이 필요했습니다."},"2":{"who":"아네트","text":"점검 합격. 그로크 대장님의 규정 위반 요청은 기각되었습니다."},"3":{"who":"아네트","text":"점검 전원 합격, 만족도 최상."}}},{"id":"F4-10","no":10,"title":"야간 폭격 비공정 모함","boss":true,"before":[{"who":"클레어","text":"제국 야간 폭격 비공정 모함. 밤하늘에 검은 날개가 펼쳐졌습니다."},{"who":"제국 함장(목소리)","text":"폭격 개시다! 연방 여러분, 어서 도망가라!"},{"who":"그로크","text":"대장님 지시입니다, 함장님은 로나 교관님께 사과해야 합니다!"},{"who":"제국 함장(목소리)","text":"로나? 누구냐. 사과라니?"},{"who":"로나","text":"저입니다. 지난 주에 방문하셨죠. 차트에 「함장 직급, 음성 크기 최대」라고 적혀 있습니다."},{"who":"제국 함장(목소리)","text":"…크흠. 모함을 내리겠다."}],"after":[{"who":"제국 함장(목소리)","text":"졌다. 오늘 밤은 정말로 졌다. 추락하는 중이다."},{"who":"그레타","text":"추락 중인데 목소리가 신나 보이구만."},{"who":"제국 함장(목소리)","text":"낙하산은 있지만 일부러 안 펼치겠다."},{"who":"클레어","text":"4장 종료입니다. 도심 야간 방어에 성공했습니다."},{"who":"아네트","text":"낙하 지점에 대기석을 마련하겠습니다."}],"stars":{"1":{"who":"아네트","text":"모함이 반파되어 도심 일부에 잔해가 떨어졌습니다."},"2":{"who":"아네트","text":"모함 격추. 함장님은 낙하산을 펼치지 않으셨습니다."},"3":{"who":"아네트","text":"모함 격추, 함장 낙하 지점 대기석 준비 완료."}}}]},"F5":{"chapter":"F5","title":"철혈의 평원","line":"female","episodes":[{"id":"F5-1","no":1,"title":"총공세의 아침","boss":false,"before":[{"who":"클레어","text":"제국이 총공세를 시작했습니다. 철혈의 평원 전역에 전차가 깔렸습니다. 8인 전원 점호하겠습니다."},{"who":"톰","text":"1번 톰, 초커 상태 양호."},{"who":"렌","text":"2번 렌이다. 오늘은 내가 먼저 정화방 예약을 걸었다."},{"who":"그레타","text":"중위가 자진해서 예약했구만. 세상이 바뀌었어."},{"who":"렌","text":"바뀐 것은 세상이지 내 신념이 아니다. 신념은 예약 후에도 유지된다."},{"who":"카이단","text":"3번 카이단! 꼬리 컨디션 최고예요!"},{"who":"그로크","text":"4번 그로크입니다. 오늘 평가는 가혹하게 부탁드립니다."},{"who":"아네트","text":"전원 정상입니다."}],"after":[{"who":"클레어","text":"선봉 격퇴. 병사 40명 포획."},{"who":"제국 병사","text":"포획이라니, 드디어 예약이 되었군. 감사하다."},{"who":"아네트","text":"번호표를 순서대로 받아 가세요."},{"who":"렌","text":"번호표 정리는 내가 돕겠다. (자기 번호는 그대로 둔다)"}],"stars":{"1":{"who":"아네트","text":"방어선이 흔들렸습니다. 번호표 배부가 지연되었습니다."},"2":{"who":"아네트","text":"방어 성공. 번호표 일부가 모래에 묻혔습니다."},"3":{"who":"아네트","text":"총공세 첫 방어 성공, 병사 만족도 최상."}}},{"id":"F5-2","no":2,"title":"전선이 흔들린다","boss":false,"before":[{"who":"아네트","text":"제국 주력 부대가 평원 중앙에 집결했습니다. 사기가 높아 보입니다."},{"who":"제국 병사","text":"우리는 연방을 무너뜨릴 것이다! 포획되면 정말로 좋은 일이 생기므로!"},{"who":"그레타","text":"동기가 이상하구만."},{"who":"제국 병사","text":"우리 지휘관이 미리 말해 줬다. 연방에서 대기하면 간식도 준다고."},{"who":"클레어","text":"간식은 사실입니다."},{"who":"제국 병사","text":"사실이었다니!"}],"after":[{"who":"아네트","text":"병사 대부분이 자발적으로 무기를 내려놓았습니다."},{"who":"그레타","text":"이건 전쟁이 아니라 입장 행사구만."},{"who":"클레어","text":"줄은 반대편으로 서세요. 입구가 저쪽입니다."}],"stars":{"1":{"who":"아네트","text":"줄 서기가 혼란스러워 현장이 소란스러워졌습니다."},"2":{"who":"아네트","text":"정리 양호. 일부 병사가 줄 순서로 다투셨습니다."},"3":{"who":"아네트","text":"전선 정리 완료, 입장 행사 만족도 최상."}}},{"id":"F5-3","no":3,"title":"철도 위의 통행료","boss":false,"before":[{"who":"자하라","text":"안녕하세요, 연방 여러분. 이 구간 통행료는 금화 5닢입니다. 제국 의뢰로 선로를 지키고 있어요."},{"who":"클레어","text":"통행료는 납부하겠습니다. 다만 영수증에 「정화 서비스 포함」이라고 적어 주세요."},{"who":"자하라","text":"서비스 포함이면 가격이 올라가는데요."},{"who":"카이단","text":"주인님, 제가 돈 대신 물어 올게요! 선로 옆에서 간식이라도!"},{"who":"자하라","text":"간식은 요금 제외입니다. 하지만 꼬리 감기를 서비스로 드릴게요."},{"who":"그레타","text":"서비스 꼬리라니 별 거 다 있구만."}],"after":[{"who":"자하라","text":"통행료 정산 끝. 오늘은 제가 손해 봤네요."},{"who":"아네트","text":"대신 재방문 권유서 다섯 장을 드립니다."},{"who":"자하라","text":"다섯 장이면 거의 한 달치입니다. 받겠습니다."},{"who":"실비아","text":"정중하게 말씀드립니다. 자하라 씨의 꼬리 감기를 한 번 더 보고 싶습니다."},{"who":"자하라","text":"1회 금화 3닢."},{"who":"실비아","text":"4닢 드리겠습니다. 팁 포함입니다."}],"stars":{"1":{"who":"아네트","text":"통행료 협상 지연. 선로 위 대기열이 길어졌습니다."},"2":{"who":"아네트","text":"통과 성공. 영수증 항목이 일부 누락되었습니다."},"3":{"who":"아네트","text":"선로 통과, 정산 완료, 자하라 씨 재방문 확정."}}},{"id":"F5-4","no":4,"title":"참호 속 도시락","boss":false,"before":[{"who":"클레어","text":"점심시간입니다. 양쪽 참호 모두 휴전입니다."},{"who":"톰","text":"도시락 8인분 준비했습니다. 딸이 좋아하던 주먹밥입니다."},{"who":"제국 병사","text":"(참호 건너편에서) 우리도 한 입 줄 수 있나!"},{"who":"톰","text":"물론이죠. 여기 넘겨 드릴게요. 대신 그쪽 소시지도 하나 주세요."},{"who":"렌","text":"식량 교환은 정보전이다. 반드시 감시하겠다."},{"who":"그레타","text":"교환하는 중위 손이 제일 빠르구만."}],"after":[{"who":"아네트","text":"휴전 후 전투 재개. 병사 25명이 도시락 교환 중이어서 전투에서 이탈했습니다."},{"who":"톰","text":"식후 정화가 가장 좋다고 하더군요."},{"who":"클레어","text":"소화에도 좋다고 들었습니다."}],"stars":{"1":{"who":"아네트","text":"휴전 연장으로 전투가 지연되었습니다."},"2":{"who":"아네트","text":"성공. 일부 병사가 과식으로 이탈했습니다."},"3":{"who":"아네트","text":"도시락 교환 성공, 병사 포획 및 간식 만족도 최상."}}},{"id":"F5-5","no":5,"title":"구속 대전","boss":false,"before":[{"who":"클레어","text":"제국이 새로운 전술을 선보였습니다. 「구속 대전」입니다."},{"who":"제국 병사","text":"연방 병사를 묶고, 연방도 우리를 묶는 방식이다! 쌍방 구속전이다!"},{"who":"아네트","text":"쌍방이 서로 묶이면 전선이 어떻게 되죠?"},{"who":"제국 병사","text":"전부 묶이면 아무도 못 움직인다! 그게 목적이다!"},{"who":"그레타","text":"묶이는 게 목적이라니, 이건 전술이 아니라 취향이구만."},{"who":"카이단","text":"주인님, 저도 묶일래요!"},{"who":"클레어","text":"안 됩니다. 이번엔 승리가 우선입니다."}],"after":[{"who":"제국 병사","text":"(묶인 채로) 이 기분은 뭐지. 지고 있는데 행복하다."},{"who":"연방 병사","text":"(묶인 채로) 저도입니다. 이긴 건지 졌는지 모르겠어요."},{"who":"클레어","text":"승패는 아네트가 판정합니다."},{"who":"아네트","text":"모두 승리입니다. 쌍방 만족도 100%."}],"stars":{"1":{"who":"아네트","text":"승패 판정 불가. 쌍방 모두 즐거워서 기록이 어렵습니다."},"2":{"who":"아네트","text":"승리. 일부 병사가 묶인 채로 잠들었습니다."},"3":{"who":"아네트","text":"구속 대전 압도적 승리, 쌍방 만족도 최상."}}},{"id":"F5-6","no":6,"title":"노예 8인의 회식","boss":false,"before":[{"who":"톰","text":"회식 시간입니다. 주인님 4분과 노예 4명, 8인이 한자리에 모였네요."},{"who":"클레어","text":"오늘은 홍차 말고 와인을 준비했습니다."},{"who":"그로크","text":"제 건배사를 하겠습니다. 「오늘도 평가는 하!」"},{"who":"로나","text":"(옆자리에서) 평가는 「하」입니다."},{"who":"그로크","text":"감사합니다!"},{"who":"카이단","text":"렌 중위님, 건배해요! 저랑 같이 목 늘이고 건배!"},{"who":"렌","text":"건배한다. …초커를 부딪쳐도 되나."}],"after":[{"who":"그레타","text":"회식 중에도 적이 습격하는 건 정해진 코스구만."},{"who":"아네트","text":"습격 병력 18명 포획. 회식 비용은 제국 부담으로 처리합니다."},{"who":"제국 병사","text":"우리가 회식비를 낸다고? 기꺼이 낸다!"}],"stars":{"1":{"who":"아네트","text":"습격으로 회식이 중단되었습니다."},"2":{"who":"아네트","text":"격퇴 성공. 와인 한 병이 파손되었습니다."},"3":{"who":"아네트","text":"회식 습격 격퇴, 비용 전액 청구 완료."}}},{"id":"F5-7","no":7,"title":"근위대장 루시안의 납치","boss":false,"before":[{"who":"아네트","text":"연방 근위대장 루시안이 평원 북쪽에서 실종되었습니다. 엘프 마도사로 알려진 인물입니다."},{"who":"루시안","text":"(통신으로) 클레어 사령관님. 저는 제국에 납치된 것으로 보입니다. 목줄이 없는 상태입니다."},{"who":"그레타","text":"목줄이 없어서 오히려 불편하다니 이게 무슨 말이구만."},{"who":"루시안","text":"연방 시절의 습관입니다. 모범 노예로서 항상 착용해 왔습니다. 목이 허전합니다."},{"who":"클레어","text":"구출 작전을 개시하겠습니다."},{"who":"루시안","text":"감사합니다. 다만 제국 병사들이 저를 「해방된 동포」라고 부르며 극진히 대합니다."}],"after":[{"who":"아네트","text":"루시안 구출은 실패했으나 위치는 확인했습니다. 제국 요새 내부입니다."},{"who":"클레어","text":"루시안은 곧 되찾겠습니다."},{"who":"렌","text":"목줄 없는 근위대장이라니. 상상만 해도 낯설다."},{"who":"톰","text":"옆에서 담요라도 건네줘야 할 텐데요."}],"stars":{"1":{"who":"아네트","text":"위치 확인 지연. 구출에 시간이 더 필요합니다."},"2":{"who":"아네트","text":"위치 확인. 통신이 중간에 끊겼습니다."},"3":{"who":"아네트","text":"위치 확인 성공, 루시안 안전 확인."}}},{"id":"F5-8","no":8,"title":"요새 앞의 대치","boss":false,"before":[{"who":"클레어","text":"제국의 거대 요새가 보입니다. 총사령관 베르단의 사령탑입니다."},{"who":"베르단","text":"(확성기) 연방의 클레어 사령관. 귀하의 도구 관리가 훌륭하다고 소문이 자자하오."},{"who":"클레어","text":"칭찬 고맙습니다. 귀하의 족쇄 설계도 감탄했습니다. 3미터 규정 개정안이 특히 마음에 듭니다."},{"who":"베르단","text":"하하, 그걸 알아보다니. 오늘 전투는 정중하게 치르겠소."},{"who":"그레타","text":"정중한 대치구만. 어디서 이렇게 사근사근한 전쟁을 보나."}],"after":[{"who":"베르단","text":"오늘은 여기까지. 내일 전면전에서 만나겠소."},{"who":"클레어","text":"내일 뵙겠습니다. 도시락은 직접 준비하겠습니다."},{"who":"베르단","text":"도시락은 우리가 준비하겠소."}],"stars":{"1":{"who":"아네트","text":"대치가 길어졌습니다. 간식 시간이 연기되었습니다."},"2":{"who":"아네트","text":"대치 양호. 일부 발언이 과장되었습니다."},"3":{"who":"아네트","text":"대치 완벽, 사령관 간 예절 교환 성공."}}},{"id":"F5-9","no":9,"title":"전야의 점검과 예약","boss":false,"before":[{"who":"아네트","text":"내일은 최종 보스전입니다. 전원 점검과 예약을 함께 진행합니다."},{"who":"렌","text":"내 예약은 이미 해 놨다. 전야제는 마음 단단히 먹고 임한다."},{"who":"카이단","text":"렌 중위님, 오늘은 같이 자요! 서로 꼬리 대신 목줄 맞대고!"},{"who":"렌","text":"…목줄은 맞대지 않는다. 다만 나란히 눕는 건 허락한다."},{"who":"톰","text":"저도 옆에 누울게요. 담요가 세 장이면 충분합니다."},{"who":"그로크","text":"저는 로나 교관님 옆에서 자겠습니다."},{"who":"로나","text":"2미터 거리를 유지하세요."},{"who":"그로크","text":"알겠습니다."}],"after":[{"who":"클레어","text":"모두 좋은 밤입니다. 내일은 전선 전체가 걸립니다."},{"who":"아네트","text":"차트는 제가 정리해 두겠습니다."},{"who":"그레타","text":"오늘 밤은 편하게 자겠구만."}],"stars":{"1":{"who":"아네트","text":"점검이 지연되었습니다. 대원 일부가 아직 깨어 있습니다."},"2":{"who":"아네트","text":"점검 양호. 일부 대원이 서로 붙어서 잠들었습니다."},"3":{"who":"아네트","text":"전야 점검 완벽, 전원 숙면."}}},{"id":"F5-10","no":10,"title":"철혈 기갑 요새","boss":true,"before":[{"who":"베르단","text":"연방의 클레어 사령관, 이 요새는 내 자부심이오. 철혈의 이름을 걸고 싸우겠소."},{"who":"클레어","text":"저도 연방의 이름을 걸고 정중하게 맞서겠습니다."},{"who":"그레타","text":"서로 도구를 칭찬하더니 이제야 진짜 싸움이구만."},{"who":"베르단","text":"병사들은 나가라! 전원 구속 대전 개시!"},{"who":"제국 병사","text":"구속 대전 개시! (전원 자진해서 묶이러 달려온다)"},{"who":"연방 병사","text":"저희도 개시! (똑같이 달려간다)"},{"who":"아네트","text":"전선이 흔들립니다. 양쪽 모두 기뻐서."}],"after":[{"who":"베르단","text":"졌소. 훌륭한 승부였소."},{"who":"클레어","text":"귀하도 훌륭하셨습니다. 요새 내부는 어떻습니까."},{"who":"베르단","text":"병사들은 대체로 행복하오. 포로라기보다 신규 입소자 같소."},{"who":"그레타","text":"이건 전쟁이 끝난 게 아니라 입소식이 끝난 것 같구만."},{"who":"아네트","text":"(하늘을 올려다보며) 클레어 사령관님, 전선 상공에 분홍빛 균열이 보입니다."},{"who":"클레어","text":"…정체를 알 수 없는 빛이군요. 경계 태세를 유지합니다."},{"who":"톰","text":"하늘이 갈라진 건가요? 담요 덮어야 하나요."},{"who":"클레어","text":"5장 종료입니다. 아직 끝이 아닙니다."}],"stars":{"1":{"who":"아네트","text":"요새 반파. 균열의 정체를 파악하지 못했습니다."},"2":{"who":"아네트","text":"요새 함락. 균열은 일시적으로 확대되었습니다."},"3":{"who":"아네트","text":"요새 함락, 쌍방 병사 만족도 최상, 상공 균열 관측."}}}]},"M1":{"chapter":"M1","title":"수도 방위","line":"male","episodes":[{"id":"M1-1","no":1,"title":"수도 낮 시가지","boss":false,"before":[{"who":"베르단","text":"연방 침투대가 수도 낮 시가지에 들어왔다. 시민이 놀라지 않도록 정중히 맞이하라."},{"who":"이그니스","text":"놀랄 시민은 이미 구경 나와 있다. 간식도 팔고 있구만."},{"who":"코그","text":"오늘의 신제품 시연입니다! 「쇠사슬 철퇴 2호」, 「훈도시 장갑복 개량형」, 「페로몬 연막탄 딸기맛」! 전부 시험해 보고 싶어서 어젯밤 잠을 못 잤습니다!"},{"who":"베르단","text":"시험은 전투 중에 하라. 시험 결과는 보고서로."},{"who":"연방 병사","text":"우리는 제국 수도를 뺏으러 왔다!"},{"who":"코그","text":"반갑습니다, 연방 병사님! 철퇴 한 방 맞아 보시겠습니까, 아니면 연막탄이 좋으십니까?"}],"after":[{"who":"코그","text":"시험 결과 철퇴 만족도 4.7, 연막탄 4.9! 병사님들이 줄 서서 맞았습니다!"},{"who":"이그니스","text":"맞으러 오는 건지 맞추러 오는 건지 모르겠구만."},{"who":"베르단","text":"상관없다. 보고서에 정확히 기재하라."}],"stars":{"1":{"who":"코그","text":"시험 지연! 연막탄이 너무 약해서 기분 좋게만 만들어 버렸습니다!"},"2":{"who":"코그","text":"시험 성공! 그런데 철퇴에 병사 한 분이 붙어서 안 떨어집니다!"},"3":{"who":"코그","text":"시험 성공! 철퇴 반응 4.7, 연막탄 4.9! 최고입니다!"}}},{"id":"M1-2","no":2,"title":"훈도시 장갑복 품평회","boss":false,"before":[{"who":"코그","text":"오늘은 훈도시 장갑복 품평회를 겸합니다! 연방 병사님들 앞에서 입어 보겠습니다!"},{"who":"이그니스","text":"내가 입을 수는 없구만. 장인은 천 한 장으로 지키지 않는다."},{"who":"베르단","text":"장교는 직접 시연하지 않는다."},{"who":"코그","text":"그럼 제가! (입는다) 어때요, 방어력 12%, 통풍성 100%입니다!"},{"who":"연방 병사","text":"시야 차단이다! 부끄럽다! …아니, 전혀 부끄럽지 않다!"},{"who":"이그니스","text":"부끄러워하는 병사가 오히려 드물구만."}],"after":[{"who":"코그","text":"품평 점수 4.5! 연방 병사님 3명이 구매 문의를 주셨습니다!"},{"who":"베르단","text":"장사가 되는 전투라니 새롭군."}],"stars":{"1":{"who":"코그","text":"반응 저조! 훈도시가 바람에 날아갔습니다!"},"2":{"who":"코그","text":"성공! 다만 사이즈 문의가 몰려서 재고가 부족합니다!"},"3":{"who":"코그","text":"품평회 대성공! 주문 서른 건!"}}},{"id":"M1-3","no":3,"title":"오크 용병의 사이즈","boss":false,"before":[{"who":"코그","text":"오늘은 오크 용병대원이 연방 여병사를 상대합니다! 이쪽이 대원 오그, 이쪽이 연방 신병 미나 씨!"},{"who":"오그","text":"그렇게 굳을 필요 없어요. 난 생각보다 거칠지 않다구. 어서 이리 오세요."},{"who":"미나","text":"저…는 사람이구요. 그쪽은 오크이신데. 「사이즈」가 다른데…… 거칠지 않다구요?"},{"who":"오그","text":"응? 사이즈? 이거 말인가???"},{"who":"미나","text":"(털썩, 기절)"},{"who":"오그","text":"대장!!! 오크 여성 좀 잡아 달라구요!!! 제발…… 이번 달 벌써 몇 명째냐구요!!!"},{"who":"이그니스","text":"이번 달 벌써 넷째 기절이구만."}],"after":[{"who":"코그","text":"기록 갱신입니다! 이번 달 기절 수 4명!"},{"who":"베르단","text":"이것은 전술이 아니라 사고다. 오그에게 교육을 시켜라."},{"who":"오그","text":"교육이라니요, 저는 정말 거칠지 않습니다."},{"who":"이그니스","text":"거칠지 않은 게 문제가 아니라 크기가 문제구만."}],"stars":{"1":{"who":"코그","text":"기절 5명! 이번 달 기록입니다!"},"2":{"who":"코그","text":"기절 3명. 한 분은 깨어난 뒤 한 번 더 기절했습니다!"},"3":{"who":"코그","text":"기절 4명 확인! 오그 씨 반성문 제출 완료!"}}},{"id":"M1-4","no":4,"title":"페로몬 연막탄의 시험","boss":false,"before":[{"who":"코그","text":"오늘은 딸기 연막탄의 실전 시험입니다! 연방 진영 한가운데 투척합니다!"},{"who":"이그니스","text":"우리 쪽으로 오면 어쩌나."},{"who":"코그","text":"풍향은 계산했습니다! 북서풍, 시속 4미터!"},{"who":"연방 병사","text":"연기다! 아, 딸기 향이다! 다리에 힘이 풀린다!"},{"who":"베르단","text":"효과가 즉각적이군."},{"who":"이그니스","text":"바람이 바뀌었다! 우리 쪽이다!"},{"who":"코그","text":"어, 그건 계산 밖입니다!"}],"after":[{"who":"이그니스","text":"우리 쪽도 딸기 향이구만. 정신 차려라."},{"who":"베르단","text":"연막 내성은 업무 능력과 무관하다. …다만 오늘은 평소보다 졸음이 온다."},{"who":"코그","text":"보고서에는 「풍향 오차」라고 적겠습니다!"}],"stars":{"1":{"who":"코그","text":"풍향 오차 대실패! 연막이 사령탑까지 닿았습니다!"},"2":{"who":"코그","text":"성공! 아군 피해 약간이지만 졸음이 오셨던 분들은 쉬세요!"},"3":{"who":"코그","text":"시험 성공! 풍향 오차는 비밀입니다!"}}},{"id":"M1-5","no":5,"title":"의무관 로제","boss":false,"before":[{"who":"코그","text":"연방 의무관 로제 씨가 부상병을 치료하고 있습니다! 연막 속에 갇히기 직전입니다!"},{"who":"로제","text":"어머, 연막이네요. 이 향은 딸기군요. 흡입 후 5분 이내에 의식이 풀리는 걸로 알고 있습니다."},{"who":"이그니스","text":"의무관이 이렇게 능청스러운 얼굴을 하다니."},{"who":"로제","text":"전장에서 능청은 기본이죠. 그런데 저를 잡으시면 어떻게 되나요?"},{"who":"코그","text":"정화 시퀀스에 들어갑니다!"},{"who":"로제","text":"정화 시퀀스가 뭔가요? 설명서가 있으면 읽고 싶은데요."}],"after":[{"who":"이그니스","text":"오늘도 어김없이…… 정화 시퀀스다!! 긴장하는 게 좋을 거다, 암노예들아!!!"},{"who":"로제","text":"네~~~~~~~~!! (하트 뿅뿅)"},{"who":"이그니스","text":"어, 이거 왜 이래. 이봐!! 겁먹으란 말이다! 내 손에 든 이 무시무시한 기구가 안 보이냔 말이다!!"},{"who":"로제","text":"보이죠!! 그래서 기분 좋아진 건데요. 어서 가죠! 정화방……"},{"who":"베르단","text":"노예가 주인을 끌고 가는 것은 규정 위반이다."},{"who":"로제","text":"위반 아닙니다. 안내입니다."}],"stars":{"1":{"who":"코그","text":"합류했는데 로제 씨가 먼저 정화방 문을 열었습니다!"},"2":{"who":"코그","text":"합류! 이그니스 상사님의 당황도가 평소보다 12% 높습니다!"},"3":{"who":"코그","text":"로제 씨 합류! 정화 시퀀스 호응도 최고!"}}},{"id":"M1-6","no":6,"title":"로제의 건강 검진","boss":false,"before":[{"who":"로제","text":"합류 기념으로 주인님들의 건강 검진을 해 드릴게요. 이그니스 상사님부터요."},{"who":"이그니스","text":"나는 건강하다! 검진은 필요 없다!"},{"who":"로제","text":"어머, 호흡이 가쁘시네요. 심박 110. 어제 야근하셨죠."},{"who":"이그니스","text":"야근이 아니라 철야다."},{"who":"베르단","text":"장군은 검진 대상이 아니다."},{"who":"로제","text":"검진은 규정입니다. 그리고 규정에 따라 그 장갑 안도 확인해야 하는데요."},{"who":"베르단","text":"…확인 부위는 최소한으로 하라."}],"after":[{"who":"로제","text":"검진 결과, 세 분 모두 「과로 및 스트레스 과다」. 처방은 정화방 일주일입니다."},{"who":"이그니스","text":"처방이 이상한 쪽으로 새는구만."},{"who":"코그","text":"저는 이미 정화방이 처방입니다!"},{"who":"로제","text":"코그 씨는 좀 쉬세요."}],"stars":{"1":{"who":"코그","text":"검진 지연! 베르단 장군님이 서류부터 달라고 하십니다!"},"2":{"who":"코그","text":"검진 양호! 이그니스 상사님이 중간에 도망치려 하셨습니다!"},"3":{"who":"코그","text":"검진 대성공! 처방 만족도 최상!"}}},{"id":"M1-7","no":7,"title":"키 얘기는 하지 마","boss":false,"before":[{"who":"코그","text":"연방 정찰병 핀 씨가 접근 중입니다! 키가 작다는 보고가 있습니다!"},{"who":"핀","text":"누가 작다는 거야! 나는 평균이야! 평균에서 조금 모자란 정도라고!"},{"who":"이그니스","text":"평균에서 조금 모자란 정도라면 작은 편이구만."},{"who":"핀","text":"작다고 하지 마!! (돌진한다)"},{"who":"코그","text":"개조 그물 발사!"},{"who":"핀","text":"이딴 그물에 걸릴까 보냐! 걸렸다! 아 놔!"}],"after":[{"who":"핀","text":"이거 풀어! 이 변태들아! 나는 연방 정찰병이야!"},{"who":"코그","text":"핀 씨, 얼굴이 새빨갛습니다!"},{"who":"핀","text":"이건 분노야! 분노로 빨개진 거라고!"},{"who":"이그니스","text":"오늘도 어김없이…… 정화 시퀀스다!! 긴장하는 게 좋을 거다, 암노예들아!!!"},{"who":"로제","text":"네~~~~~!! (하트 뿅뿅)"},{"who":"핀","text":"나는 노예 아니야! 그리고 왜 같이 외치는 거야!"}],"stars":{"1":{"who":"코그","text":"합류! 소리 지르는 데시벨이 정화방 벽을 울립니다!"},"2":{"who":"코그","text":"합류! 핀 씨는 합류 후에도 소리를 지르십니다!"},"3":{"who":"코그","text":"핀 씨 합류! 그물 반응 최고, 얼굴 색상 5단계 중 5!"}}},{"id":"M1-8","no":8,"title":"정화방 입실 거부","boss":false,"before":[{"who":"핀","text":"나는 정화방에 안 가! 절대로 안 가! 도망칠 거야!"},{"who":"이그니스","text":"족쇄 3미터 규정을 모르는 모양이구만."},{"who":"핀","text":"3미터 밖으로 나가면 되잖아!"},{"who":"코그","text":"3미터 넘으면 당겨집니다! 시험해 보시겠습니까!"},{"who":"핀","text":"시험해 본다! (달린다, 당겨진다) 으아아악!"},{"who":"로제","text":"어머, 당겨지는 것도 즐기시는 눈치네요."},{"who":"핀","text":"즐기는 거 아니야!"}],"after":[{"who":"핀","text":"…다녀왔어. 아무 일도 없었어. 아무것도 안 했어."},{"who":"로제","text":"얼굴이 빨개요, 핀 씨."},{"who":"핀","text":"분노야! 분노라고!"},{"who":"이그니스","text":"분노가 그렇게 말랑해진 건 처음 보는구만."}],"stars":{"1":{"who":"코그","text":"입실 지연! 핀 씨가 천장 파이프에 매달리셨습니다!"},"2":{"who":"코그","text":"입실 성공! 핀 씨는 퇴실 후에도 불평하십니다!"},"3":{"who":"코그","text":"입실 성공! 핀 씨 불평 감소율 60%!"}}},{"id":"M1-9","no":9,"title":"전야의 도발","boss":false,"before":[{"who":"클레어","text":"(통신) 제국의 주인 여러분, 안녕하세요. 내일 만나게 되어 기쁩니다."},{"who":"베르단","text":"연방 총사령관. 정중한 인사에 감사한다. 내일은 우리가 이긴다."},{"who":"클레어","text":"이기시면 홍차를 대접하겠습니다. 지시면 족쇄를 대접하고요."},{"who":"이그니스","text":"대접이 이상한 방향이구만."},{"who":"로제","text":"저쪽 사령관님, 말씀이 친절하시네요. 제가 연방에 있을 땐 몰랐는데."},{"who":"핀","text":"우리 사령관이 저렇게 친절하다니 믿을 수 없어."}],"after":[{"who":"코그","text":"내일 보스전 준비 완료! X자 구속 전차를 해체할 장비도 챙겼습니다!"},{"who":"베르단","text":"좋은 밤이다. 전원 휴식하라."},{"who":"로제","text":"주인님들, 주무시기 전에 건강 차 한 잔씩 드세요."},{"who":"이그니스","text":"이 차는 맛이 이상한데."},{"who":"로제","text":"수면 유도제입니다. 오늘은 푹 주무세요."}],"stars":{"1":{"who":"코그","text":"점검 지연! 통신 기기에 홍차가 쏟아졌습니다!"},"2":{"who":"코그","text":"점검 양호! 이그니스 상사님이 아직 눈을 뜨고 계십니다!"},"3":{"who":"코그","text":"전야 점검 완벽! 전원 숙면 예정!"}}},{"id":"M1-10","no":10,"title":"X자 구속 전차","boss":true,"before":[{"who":"연방 지휘관(목소리)","text":"제국의 주인들, 이 전차는 X자 구속 전차다. 한 번 걸리면 풀 수 없다!"},{"who":"코그","text":"X자로 묶는다니, 이건 연구 가치가 큽니다! 해체해서 구조를 보고 싶습니다!"},{"who":"베르단","text":"해체는 전투 후에 하라."},{"who":"이그니스","text":"이름만 들어도 묶일 것 같구만."},{"who":"로제","text":"저도 한 번 묶여 보고 싶네요."},{"who":"핀","text":"나는 묶이기 싫어!"}],"after":[{"who":"코그","text":"전차 해체 완료! 구조 파악했습니다!"},{"who":"베르단","text":"1장 종료다. 수도 방어에 성공했다."},{"who":"로제","text":"오늘 밤 정화 시퀀스는 제가 먼저 콜해도 될까요?"},{"who":"이그니스","text":"콜은 내가 한다!"},{"who":"핀","text":"…나는 콜 안 해."}],"stars":{"1":{"who":"코그","text":"전차 반파! 그런데 조종사가 내리지 않고 있습니다!"},"2":{"who":"코그","text":"전차 해체! 연방 지휘관이 구속 상태에서 행복해하십니다!"},"3":{"who":"코그","text":"전차 해체! 주문 폭주 예상!"}}}]},"M2":{"chapter":"M2","title":"밤하늘 편대전","line":"male","episodes":[{"id":"M2-1","no":1,"title":"하피 야간 편대","boss":false,"before":[{"who":"코그","text":"밤하늘에 연방 하피 편대가 떴습니다! 깃털이 반짝입니다!"},{"who":"이그니스","text":"깃털로 공격하는 건가."},{"who":"벨루가","text":"(상공에서) 안녕, 제국 여러분! 오늘 가스는 포도 향이야!"},{"who":"베르단","text":"아군 상공이 아니다. 대공포 준비."},{"who":"로제","text":"포도 향이라면 소화가 잘 되는 계열이네요. 흡입해도 무해합니다."},{"who":"핀","text":"흡입하지 마! 정신 차려!"}],"after":[{"who":"코그","text":"하피 편대 격퇴! 깃털 12개 수집! 간지럼 장비로 쓸 수 있습니다!"},{"who":"이그니스","text":"깃털을 줍는 병사가 줄 서 있구만."},{"who":"베르단","text":"그만 줍고 보고하라."}],"stars":{"1":{"who":"코그","text":"편대가 도주했습니다! 깃털만 남았습니다!"},"2":{"who":"코그","text":"격퇴 성공! 깃털 몇 개가 바람에 날아갔습니다!"},"3":{"who":"코그","text":"편대 격퇴 대성공! 깃털 수집 12개!"}}},{"id":"M2-2","no":2,"title":"달빛 아래의 점호","boss":false,"before":[{"who":"베르단","text":"야간 점호를 시작한다. 로제, 핀 보고하라."},{"who":"로제","text":"1번 로제입니다. 정화방 예약은 이미 걸어 두었습니다."},{"who":"이그니스","text":"노예가 먼저 예약을 걸다니 규정에 있나."},{"who":"로제","text":"규정집 제12조에 「노예의 자발적 예약은 환영한다」라고 되어 있습니다."},{"who":"핀","text":"2번 핀. 나는 예약 안 걸었어. 로제가 대신 걸었어."},{"who":"로제","text":"핀 씨 이름으로 걸었어요. 취소하시려면 직접 가서 말씀하세요."},{"who":"핀","text":"…안 가. 취소하러 가는 길에 정화방 앞을 지나가는 건 불가피해."}],"after":[{"who":"코그","text":"점호 완료! 핀 씨, 정화방 앞에서 한참 서 계셨습니다!"},{"who":"핀","text":"신발끈 묶고 있었어!"},{"who":"이그니스","text":"신발끈 묶는 데 20분 걸리는 건 처음 보는구만."}],"stars":{"1":{"who":"코그","text":"점호 지연! 핀 씨가 신발끈을 세 번 푸셨습니다!"},"2":{"who":"코그","text":"점호 양호! 핀 씨 불평 횟수 12회!"},"3":{"who":"코그","text":"점호 완벽! 핀 씨 정화방 앞 대기 시간 20분!"}}},{"id":"M2-3","no":3,"title":"오크 용병 야간 순찰","boss":false,"before":[{"who":"코그","text":"야간 순찰은 오크 용병대원 오그 씨와 연방 신병이 합동으로 돕니다!"},{"who":"오그","text":"그렇게 굳을 필요 없어요. 난 생각보다 거칠지 않다구."},{"who":"연방 여병사","text":"저…는 사람인데요. 오크님은 「사이즈」가…… (털썩)"},{"who":"오그","text":"대장!!! 오크 여성 좀 잡아 달라구요!!! 이번 달 벌써 다섯째라구요!!!"},{"who":"이그니스","text":"다섯째가 아니라 이번 야간에만 둘째구만."},{"who":"로제","text":"어머, 기절하신 분은 제가 치료할게요. 사이즈 얘기는 접어 두죠."}],"after":[{"who":"코그","text":"이번 달 기절 수 누적 7명!"},{"who":"베르단","text":"누적 숫자를 낭독하지 마라."},{"who":"오그","text":"죄송합니다. 정말로 거칠지 않습니다."},{"who":"이그니스","text":"크기가 문제구만, 크기가."}],"stars":{"1":{"who":"코그","text":"기절 8명! 이번 달 기록 경신!"},"2":{"who":"코그","text":"기절 7명! 로제 씨가 3명 연속 인공호흡 대신 인공 호흡기를 쓰셨습니다!"},"3":{"who":"코그","text":"기절자 응급 처치 100%, 누적 7명!"}}},{"id":"M2-4","no":4,"title":"핀의 불평 일기","boss":false,"before":[{"who":"핀","text":"(일기장에 쓰며) 오늘의 불평: 정화방 의자가 푹신해서 불쾌했다. 오늘의 불평 2: 코그의 도구가 너무 정교해서 화가 났다."},{"who":"로제","text":"어머, 불평이 칭찬으로 읽히는데요."},{"who":"핀","text":"아니거든! 불평이거든!"},{"who":"이그니스","text":"일기 마지막 줄은 뭐냐."},{"who":"핀","text":"「내일도 불평하러 갈 것」. …이상한 문장이 들어갔네. 지울게."}],"after":[{"who":"핀","text":"일기 지우다가 들켰어. 전부 불평이야. 정말이야."},{"who":"코그","text":"불평의 질이 좋습니다! 출판해도 되겠습니다!"},{"who":"핀","text":"출판하지 마!"}],"stars":{"1":{"who":"코그","text":"일기 분실! 핀 씨가 침대 밑을 뒤지고 계십니다!"},"2":{"who":"코그","text":"일기 일부 훼손! 핀 씨의 얼굴이 새빨갛습니다!"},"3":{"who":"코그","text":"일기 압수 성공, 불평 지수 최고치!"}}},{"id":"M2-5","no":5,"title":"옥상 추적전","boss":false,"before":[{"who":"코그","text":"연방 저격수가 옥상에서 우리 쪽을 겨누고 있습니다! 코드네임은 실비아!"},{"who":"실비아","text":"정중하게 말씀드립니다. 제국 여러분의 허리띠를 정확히 저격하겠습니다."},{"who":"이그니스","text":"허리띠를 쏜다는 건 바지가 흘러내린다는 뜻이구만."},{"who":"실비아","text":"문자 그대로입니다. 한 발에 한 분."},{"who":"베르단","text":"침착하라. 방패를 앞세우고 접근한다."},{"who":"로제","text":"실비아 씨는 연방 때부터 존경하던 분인데요. 쏘시면 영광입니다."}],"after":[{"who":"실비아","text":"(옥상에서 내려와) 정중하게 사과드립니다. 허리띠 22개 파손했습니다."},{"who":"이그니스","text":"사과를 하면서 환한 얼굴이구만."},{"who":"실비아","text":"일을 잘 마쳤을 때의 표정입니다."},{"who":"로제","text":"실비아 씨, 저를 한 번 쏘아 주시겠어요?"},{"who":"실비아","text":"아군이라면 허락됩니다."}],"stars":{"1":{"who":"코그","text":"실비아 도주! 허리띠만 가져갔습니다!"},"2":{"who":"코그","text":"격퇴 성공! 허리띠가 지붕 위에 흩어졌습니다!"},"3":{"who":"코그","text":"실비아 격퇴! 허리띠 손실 22개, 아군 피해 0!"}}},{"id":"M2-6","no":6,"title":"로제의 선점","boss":false,"before":[{"who":"로제","text":"정화방 예약이 모두 찼네요. 제가 먼저 다녀오겠습니다."},{"who":"핀","text":"로제! 새치기야!"},{"who":"로제","text":"새치기가 아니라 선점입니다. 순번표 1번은 이미 제 손에 있어요."},{"who":"이그니스","text":"선점이든 새치기든 뭔 차이냐."},{"who":"로제","text":"선점은 일찍 일어나서 하는 거고, 새치기는 일찍 안 일어나서 하는 거예요."},{"who":"핀","text":"나도 내일은 일찍 일어난다!"}],"after":[{"who":"로제","text":"다녀왔습니다. 얼굴이 환해졌죠."},{"who":"핀","text":"…부럽지 않아."},{"who":"로제","text":"핀 씨는 내일 같이 가시죠."},{"who":"핀","text":"같이 안 가!"}],"stars":{"1":{"who":"코그","text":"선점 지연! 이그니스 상사님이 새치기하셨습니다!"},"2":{"who":"코그","text":"선점 성공! 핀 씨가 내일 예약을 걸었습니다!"},"3":{"who":"코그","text":"로제 씨 선점 성공! 핀 씨의 부러움 지수 최고!"}}},{"id":"M2-7","no":7,"title":"깃털 시험","boss":false,"before":[{"who":"코그","text":"수집한 하피 깃털을 시험할 시간입니다! 지원자는 앞으로!"},{"who":"이그니스","text":"장인은 시험 대상이 아니다."},{"who":"코그","text":"그럼 핀 씨가!"},{"who":"핀","text":"왜 내가! 하지 마! 하지…… 으하하하하!! 하지 마!!"},{"who":"로제","text":"어머, 웃음소리가 청명하네요."},{"who":"핀","text":"아니거든! 웃음 아니거든! 하하하하!!"}],"after":[{"who":"코그","text":"시험 결과, 핀 씨의 간지럼 감도 상위 3%!"},{"who":"핀","text":"상위 3%라니, 부끄럽지 않아! 오히려 자랑스럽다!"},{"who":"이그니스","text":"부끄럽지 않은 걸 자랑스럽다고 말하는 게 이미 부끄러운 거구만."}],"stars":{"1":{"who":"코그","text":"시험 중단! 깃털이 코에 들어가 재채기가 터졌습니다!"},"2":{"who":"코그","text":"시험 성공! 핀 씨가 중간에 기절하셨습니다!"},"3":{"who":"코그","text":"시험 성공! 핀 씨 웃음 120데시벨!"}}},{"id":"M2-8","no":8,"title":"야간 시장","boss":false,"before":[{"who":"코그","text":"야간 시장이 열렸습니다! 제국과 연방 상인들이 섞여 있습니다!"},{"who":"상인","text":"오늘의 인기 상품은 쫀득 채찍입니다! 두 개 사면 하나 덤!"},{"who":"이그니스","text":"전투 중에 장을 보는 놈들이 있구만."},{"who":"로제","text":"저는 약초 코너로 가겠습니다. 정화 보조 약초가 있어요."},{"who":"핀","text":"나는 옷 가게에 갈래. …물론 필요해서 가는 거야."},{"who":"베르단","text":"가서 사 오라. 영수증 첨부."}],"after":[{"who":"코그","text":"시장 방어 성공! 상인 보호 완료!"},{"who":"상인","text":"감사합니다! 채찍 한 개 서비스로 드리겠습니다!"},{"who":"핀","text":"서비스라면 받을게. …필요해서 받는 거야."}],"stars":{"1":{"who":"코그","text":"시장 일부 파손! 보상 협상이 필요합니다!"},"2":{"who":"코그","text":"방어 성공! 상인들이 감사 인사를 길게 하셨습니다!"},"3":{"who":"코그","text":"시장 방어 대성공! 서비스 상품 획득 3종!"}}},{"id":"M2-9","no":9,"title":"전야","boss":false,"before":[{"who":"베르단","text":"내일은 보스전이다. 모두 일찍 쉬어라."},{"who":"로제","text":"주인님들, 주무시기 전에 따뜻한 차를 드릴게요."},{"who":"핀","text":"나도 한 잔. …옆에서 마시는 건 필요해서야."},{"who":"이그니스","text":"필요하다는 말이 요즘 너무 자주 나오는구만."},{"who":"코그","text":"저도 한 잔! 잠이 안 와서요!"}],"after":[{"who":"로제","text":"오늘 밤 하늘이 맑네요. 내일도 별이 잘 보이겠어요."},{"who":"핀","text":"별을 보다 보니 기분이 좋아졌어. 분명 별 때문이야."},{"who":"베르단","text":"좋은 밤이다."}],"stars":{"1":{"who":"코그","text":"점검 지연! 로제 씨의 차가 너무 맛있어서 아무도 안 잡니다!"},"2":{"who":"코그","text":"점검 양호! 핀 씨가 차를 두 잔 마셨습니다!"},"3":{"who":"코그","text":"전야 점검 완벽! 전원 숙면!"}}},{"id":"M2-10","no":10,"title":"깃털 편대 모함","boss":true,"before":[{"who":"벨루가","text":"(확성기) 연방 깃털 편대 모함 발진! 오늘 밤은 깃털이 눈처럼 쏟아질 거야!"},{"who":"코그","text":"깃털이 눈처럼! 이건 간지럼 최종병기입니다!"},{"who":"이그니스","text":"깃털 폭풍이라니 걸리면 큰일이구만."},{"who":"로제","text":"걸려도 괜찮아요. 제가 치료해 드릴게요."},{"who":"핀","text":"걸리기 싫어! 아니, 걸려도 어쩔 수 없지만!"}],"after":[{"who":"벨루가","text":"졌다! 하지만 재밌었어! 다음엔 더 큰 깃털로 올게!"},{"who":"베르단","text":"2장 종료다. 밤하늘을 지켜냈다."},{"who":"코그","text":"깃털 총 수집량 800개! 박물관을 열어도 되겠습니다!"},{"who":"핀","text":"나는 그 박물관에는 안 간다."}],"stars":{"1":{"who":"코그","text":"모함 반파! 깃털이 도시 전체에 내렸습니다!"},"2":{"who":"코그","text":"격파! 벨루가 씨가 낙하하면서도 웃고 계셨습니다!"},"3":{"who":"코그","text":"모함 격파! 깃털 800개 확보!"}}}]},"M3":{"chapter":"M3","title":"모래 먼지 구역","line":"male","episodes":[{"id":"M3-1","no":1,"title":"슬럼가의 아침 콜","boss":false,"before":[{"who":"이그니스","text":"오늘도 어김없이…… 정화 시퀀스다!! 긴장하는 게 좋을 거다, 암노예들아!!!"},{"who":"로제·핀","text":"네~~~~~~~~!! (하트 뿅뿅)"},{"who":"이그니스","text":"어, 이거 왜 이래. 이봐!! 겁먹으란 말이다! 내 손에 든 이 무시무시한 기구가 안 보이냔 말이다!!"},{"who":"로제","text":"보이죠!! 그래서 기분 좋아진 건데요. 어서 가죠! 정화방……"},{"who":"핀","text":"가죠! 아니, 난 안 가지만! …가 줄게!"},{"who":"베르단","text":"노예가 주인을 끌고 가는 것은 규정 위반이다. 그러나 오늘은 눈감아 주겠다."}],"after":[{"who":"코그","text":"슬럼가 아침 전투 종료! 병사 30명 포획!"},{"who":"이그니스","text":"콜이 점점 신나는 쪽으로 가는구만."},{"who":"로제","text":"이그니스 상사님이 점점 당황하는 쪽으로 가시는 거죠."}],"stars":{"1":{"who":"코그","text":"콜 호응 저조! 목이 쉬었습니다!"},"2":{"who":"코그","text":"콜 호응 양호! 핀 씨가 이번엔 먼저 외쳤습니다!"},"3":{"who":"코그","text":"콜 호응도 최고! 이그니스 상사님 당황도도 최고!"}}},{"id":"M3-2","no":2,"title":"모래 먼지 배급","boss":false,"before":[{"who":"코그","text":"슬럼가 주민에게 식량을 배급하는 날입니다! 연방 병사가 습격해 옵니다!"},{"who":"주민","text":"배급 줄이 길어서 짜증 나는데 전투까지 하냐!"},{"who":"연방 병사","text":"우리는 배급 줄이 아니라 제국을 뺏으러 왔다!"},{"who":"이그니스","text":"줄에 서라. 배급은 순서대로다."},{"who":"로제","text":"부상자부터 우선 배급입니다."},{"who":"핀","text":"나는 배급 줄을 정리할게. …정리하는 거야."}],"after":[{"who":"코그","text":"배급 완료! 연방 병사도 3명이 줄에 끼어 간식을 받아 갔습니다!"},{"who":"베르단","text":"간식은 적에게도 평등하다."}],"stars":{"1":{"who":"코그","text":"배급 지연! 줄이 골목을 두 바퀴 돌았습니다!"},"2":{"who":"코그","text":"배급 양호! 새치기 2건!"},"3":{"who":"코그","text":"배급 대성공! 새치기 0건!"}}},{"id":"M3-3","no":3,"title":"오크 용병대의 출동","boss":false,"before":[{"who":"그로크","text":"오크 용병대장 그로크, 도착했다. 연방 여병사들은 어디 있는가."},{"who":"오그","text":"대장!!! 오크 여성 좀 잡아 달라구요!!! 이번 달 벌써 열둘째라구요!!!"},{"who":"그로크","text":"열둘째라니, 한 달에 열둘이 기절했단 말이냐."},{"who":"이그니스","text":"열둘이다. 오늘도 둘 더 늘 것 같구만."},{"who":"그로크","text":"내가 직접 나서겠다. 연방 여병사들이여, 그렇게 굳을 필요 없다. 난 생각보다 거칠지 않다."},{"who":"연방 여병사","text":"저는 사람이고 그쪽은 오크이신데 「사이즈」가…… (털썩)"},{"who":"그로크","text":"대장도 기절시키면 안 되는데!"}],"after":[{"who":"코그","text":"기절 14명으로 월 기록 경신! 응급 처치반이 전원 출동했습니다!"},{"who":"로제","text":"응급 처치는 제가 총괄하겠습니다. 기절하신 분은 제 앞으로 눕혀 주세요."},{"who":"그로크","text":"면목 없다. 나는 정말로 거칠지 않은데."},{"who":"이그니스","text":"크기가 문제구만, 크기가."}],"stars":{"1":{"who":"코그","text":"기절 15명! 이번 달 신기록!"},"2":{"who":"코그","text":"기절 14명! 로제 씨가 처치 도중 약품을 한 통 비웠습니다!"},"3":{"who":"코그","text":"기절 14명! 응급 처치 성공률 100%!"}}},{"id":"M3-4","no":4,"title":"벨루가의 포획","boss":false,"before":[{"who":"벨루가","text":"(상공에서) 안녕, 제국 여러분! 오늘은 깃털 비를 뿌릴게!"},{"who":"코그","text":"개조 간지럼 그물, 발사!"},{"who":"벨루가","text":"어어, 그물이다! 근데 이거 재밌게 생겼네! 아하하하!"},{"who":"이그니스","text":"걸린 채로 웃고 있구만."},{"who":"벨루가","text":"웃으면 안 돼? 웃으면 규정 위반이야?"},{"who":"베르단","text":"웃는 것은 자유다."}],"after":[{"who":"벨루가","text":"잡혔네! 이제 뭐 하면 돼? 정화방이 재밌다는 소문 들었어!"},{"who":"코그","text":"벨루가 씨, 합류하시겠습니까?"},{"who":"벨루가","text":"합류! 근데 족쇄 3미터 규정은 날개가 있어서 어떻게 돼?"},{"who":"로제","text":"날개 길이를 포함해서 3미터입니다."},{"who":"벨루가","text":"그럼 3미터까지만 날면 되네!"}],"stars":{"1":{"who":"코그","text":"합류! 벨루가 씨가 천장에 걸려 내려오지 않습니다!"},"2":{"who":"코그","text":"합류! 벨루가 씨가 족쇄 위에서 곡예 비행을 하십니다!"},"3":{"who":"코그","text":"벨루가 씨 합류! 그물 반응 최고, 웃음 소리 140데시벨!"}}},{"id":"M3-5","no":5,"title":"자유분방한 하피","boss":false,"before":[{"who":"벨루가","text":"정화방 가는 길에 하늘 한 바퀴만 돌고 올게!"},{"who":"이그니스","text":"3미터 규정이다. 멀리 못 간다."},{"who":"벨루가","text":"3미터 안에서 최대한 멀리 돌게!"},{"who":"핀","text":"날아다니는 걸 보니 부럽지는 않지만…… 부러워."},{"who":"로제","text":"핀 씨도 날고 싶으세요?"},{"who":"핀","text":"아니! 그냥 높은 곳에서 불평하고 싶을 뿐이야!"}],"after":[{"who":"벨루가","text":"정화방 다녀왔어! 날개가 가벼워졌어!"},{"who":"로제","text":"날개가 가벼워지는 정화는 처음 봅니다."},{"who":"코그","text":"날개 무게 12% 감소 확인!"}],"stars":{"1":{"who":"코그","text":"비행 불안정! 날개가 족쇄에 걸렸습니다!"},"2":{"who":"코그","text":"비행 양호! 벨루가 씨가 지붕 위로 올라가 내려오지 않습니다!"},"3":{"who":"코그","text":"비행 만족도 최상! 날개 무게 12% 감소!"}}},{"id":"M3-6","no":6,"title":"이번 달 기절 수 폭증","boss":false,"before":[{"who":"코그","text":"오크 용병대가 합동으로 연방 여병사를 상대합니다! 이번 달 기절 수는 현재 18명!"},{"who":"그로크","text":"대원들! 부드럽게 접근하라! 연방 여병사들이 놀라지 않도록!"},{"who":"오그 외 대원","text":"그렇게 굳을 필요 없어요. 난 생각보다 거칠지 않다구."},{"who":"연방 여병사 다수","text":"(줄지어) 저…는 사람인데요 「사이즈」가…… (연쇄 털썩)"},{"who":"그로크","text":"오크 여성 좀 잡아 달라구요!!! 제발!!!"},{"who":"이그니스","text":"한 번에 여섯이 쓰러졌구만. 이게 효율인가."}],"after":[{"who":"코그","text":"기절 총 24명! 응급 처치반 인력 부족!"},{"who":"로제","text":"인원을 늘리겠습니다. 오크 여성 지원자를 모집하죠."},{"who":"그로크","text":"오크 여성이 오지 않는 건 사이즈 때문이 아니라 조건 때문이다."},{"who":"이그니스","text":"조건이 뭐냐."},{"who":"그로크","text":"상대 남성의 사이즈가 오크보다 커야 한다는 조건이다."},{"who":"베르단","text":"…지원자는 없을 것이다."}],"stars":{"1":{"who":"코그","text":"기절 25명! 병상이 부족합니다!"},"2":{"who":"코그","text":"기절 24명! 응급 처치반 휴식 시간을 연장합니다!"},"3":{"who":"코그","text":"기절 24명! 응급 처치 성공! 오크 여성 지원 공고 완료!"}}},{"id":"M3-7","no":7,"title":"자하라의 모래 함정","boss":false,"before":[{"who":"자하라","text":"안녕하세요, 제국 여러분. 사막 이민 구역에 오신 걸 환영합니다. 통행료는 금화 3닢입니다."},{"who":"이그니스","text":"이민 구역이 제국 영토 안에 있다니, 통행료는 누구에게 내는 거냐."},{"who":"자하라","text":"저에게요. 연방 소속 상인으로서 정당하게 받습니다."},{"who":"코그","text":"함정이 있습니다! 발밑이 모래 늪입니다!"},{"who":"자하라","text":"아직 안 빠지셨네요. 꼬리 감기 서비스는 별도 요금입니다."},{"who":"베르단","text":"서비스 요금표를 달라."}],"after":[{"who":"자하라","text":"이번엔 제가 졌지만 포획은 안 됩니다. 제 계약서엔 포획 조항이 없거든요."},{"who":"이그니스","text":"포획 조항이 없으면 어떻게 해야 하냐."},{"who":"자하라","text":"조항을 추가하시려면 협상하셔야 합니다. 수수료는 비쌉니다."},{"who":"코그","text":"협상은 장기전이겠습니다!"}],"stars":{"1":{"who":"코그","text":"돌파 지연! 병사 일부가 모래 늪에서 휴식 중입니다!"},"2":{"who":"코그","text":"돌파 성공! 자하라 씨가 요금표를 건넸습니다!"},"3":{"who":"코그","text":"모래 함정 돌파! 자하라 씨 협상 개시!"}}},{"id":"M3-8","no":8,"title":"핀의 루틴","boss":false,"before":[{"who":"핀","text":"오늘도 정화방 예약 걸었어. 불평하러 가는 거야. 매일 불평해야 하니까."},{"who":"로제","text":"불평하러 가는 게 습관이 되셨네요."},{"who":"핀","text":"습관이 아니라 의무야!"},{"who":"벨루가","text":"의무라면 같이 가자! 난 습관이야!"},{"who":"이그니스","text":"습관이든 의무든 같이 줄 서는 건 좋구만."}],"after":[{"who":"핀","text":"다녀왔어. 불평은 오늘도 충분히 했어."},{"who":"로제","text":"얼굴이 풀어지셨네요."},{"who":"핀","text":"이건 분노가 풀린 거야."}],"stars":{"1":{"who":"코그","text":"루틴 불안정! 핀 씨가 예약 날짜를 착각했습니다!"},"2":{"who":"코그","text":"루틴 양호! 핀 씨 불평이 7분으로 늘었습니다!"},"3":{"who":"코그","text":"루틴 안정! 핀 씨 불평 시간 정확히 5분!"}}},{"id":"M3-9","no":9,"title":"전야","boss":false,"before":[{"who":"베르단","text":"내일은 연방 사막 전차 「모래 상어」와 맞붙는다. 모두 휴식하라."},{"who":"벨루가","text":"휴식은 하늘에서 해도 돼?"},{"who":"베르단","text":"3미터 이내라면 허락한다."},{"who":"로제","text":"오늘 밤은 제가 야간 근무를 서겠습니다."},{"who":"핀","text":"나도 같이 서. …혼자 있으면 심심하니까."}],"after":[{"who":"코그","text":"점검 완료! 내일 준비 만전입니다!"},{"who":"이그니스","text":"모래 상어는 이빨이 날카롭다더구만."},{"who":"로제","text":"이빨 걱정은 필요 없습니다. 제가 치료해 드리겠습니다."}],"stars":{"1":{"who":"코그","text":"점검 지연! 핀 씨와 로제 씨가 새벽까지 수다를 떠셨습니다!"},"2":{"who":"코그","text":"점검 양호! 벨루가 씨가 천장에서 자고 있습니다!"},"3":{"who":"코그","text":"점검 완벽! 전원 숙면 준비 완료!"}}},{"id":"M3-10","no":10,"title":"모래 상어","boss":true,"before":[{"who":"자하라","text":"(전차 위에서) 안녕하세요, 제국 여러분. 이 전차 「모래 상어」의 조종은 제가 맡았습니다. 요금은 승리 후 청구하겠습니다."},{"who":"이그니스","text":"상인이 조종까지 하냐."},{"who":"자하라","text":"다재다능한 것이 상인의 미덕입니다. 포신 앞에 서 주세요. 과녁이 필요합니다."},{"who":"베르단","text":"과녁이 되라는 말이냐."},{"who":"코그","text":"이건 대단한 도전입니다! 해체해서 구조를 알고 싶습니다!"}],"after":[{"who":"자하라","text":"졌네요. 하지만 이번에도 포획은 안 됩니다. 도망갈 수 있는 한 도망가겠습니다."},{"who":"이그니스","text":"전차는 완파했구만."},{"who":"자하라","text":"요금은 청구하지 않겠습니다. 다음엔 제가 이길 겁니다."},{"who":"베르단","text":"3장 종료다. 슬럼가 방어에 성공했다."}],"stars":{"1":{"who":"코그","text":"반파! 자하라 씨가 전차에서 내리지 않고 계십니다!"},"2":{"who":"코그","text":"격파! 자하라 씨가 꼬리 감기로 탈출했습니다!"},"3":{"who":"코그","text":"모래 상어 격파! 자하라 씨 도주 성공!"}}}]},"M4":{"chapter":"M4","title":"정화 대성당","line":"male","episodes":[{"id":"M4-1","no":1,"title":"폐허의 아침 콜","boss":false,"before":[{"who":"이그니스","text":"오늘도 어김없이…… 정화 시퀀스다!! 긴장하는 게 좋을 거다, 암노예들아!!!"},{"who":"로제·핀·벨루가","text":"네~~~~~~~~!! (하트 뿅뿅)"},{"who":"로제","text":"오늘은 제가 1번입니다. 예약표 확인했습니다."},{"who":"핀","text":"2번이야. …누가 대신 걸어 줬지만 어쨌든 2번이야."},{"who":"벨루가","text":"3번! 하늘에서 줄 서 있어도 돼?"},{"who":"이그니스","text":"어, 이거 왜 이래. 겁먹으란 말이다. 이 기구가 안 보이냔 말이다!!"},{"who":"로제","text":"보이니까 줄 서는 겁니다. 어서 가죠, 정화방……"}],"after":[{"who":"코그","text":"병사 28명 포획! 노예 예약 경쟁률은 3대 1!"},{"who":"이그니스","text":"주인이 예약 경쟁에 밀리는 건 규정에 없는데."},{"who":"베르단","text":"규정집 제15조, 「노예의 기대는 존중한다」."}],"stars":{"1":{"who":"코그","text":"호응 저조! 이그니스 상사님 목소리가 갈라졌습니다!"},"2":{"who":"코그","text":"호응 양호! 핀 씨가 새치기를 시도했습니다!"},"3":{"who":"코그","text":"콜 호응 최고! 경쟁률 3대 1!"}}},{"id":"M4-2","no":2,"title":"순번표 경쟁","boss":false,"before":[{"who":"코그","text":"정화방 앞 대기열이 폭주합니다! 번호표 1~3번을 둘러싼 암투가 벌어지고 있습니다!"},{"who":"로제","text":"번호표는 저와 핀 씨, 벨루가 씨가 가위바위보로 정하죠."},{"who":"벨루가","text":"가위바위보는 내가 제일 잘해! 날개로 가위를 만들 수 있거든!"},{"who":"핀","text":"날개는 반칙이야!"},{"who":"베르단","text":"순번 문제로 전투가 지연되고 있다. 신속히 해결하라."},{"who":"연방 병사","text":"우리도 번호표가 필요하다!"}],"after":[{"who":"코그","text":"번호표 문제 해결! 로제 씨 1번, 벨루가 씨 2번, 핀 씨 3번!"},{"who":"핀","text":"내가 3번이라니 부당해! …하지만 3번도 괜찮아."},{"who":"이그니스","text":"노예의 순번 다툼이 주인의 일정을 결정하는 구조구만."}],"stars":{"1":{"who":"코그","text":"분쟁 지속! 줄이 건물 하나를 감쌌습니다!"},"2":{"who":"코그","text":"분쟁 해결! 벨루가 씨의 날개 가위가 심판에게 걸렸습니다!"},"3":{"who":"코그","text":"순번 분쟁 해결! 가위바위보 대회 개최!"}}},{"id":"M4-3","no":3,"title":"폐허의 보급","boss":false,"before":[{"who":"코그","text":"대성당 주변 폐허에 보급 상자가 흩어져 있습니다! 연방도 노리고 있습니다!"},{"who":"이그니스","text":"상자 안에 뭐가 들었는지 아직 모른다."},{"who":"로제","text":"열어 보지 않으면 모르죠. 부상자 치료 약품이면 좋겠는데."},{"who":"핀","text":"상자에 구속 도구가 들어 있으면 좋겠어. 아니 필요해서가 아니라 전투 목적으로."},{"who":"벨루가","text":"나는 깃털이 들어 있으면 좋겠어!"}],"after":[{"who":"코그","text":"상자 개봉! 약품 20, 쫀득 채찍 5, 깃털 100!"},{"who":"벨루가","text":"깃털이다! 소원이 이뤄졌어!"},{"who":"로제","text":"약품은 제가 정리하겠습니다."},{"who":"핀","text":"채찍은…… 내가 보관할게. 전투 목적으로."}],"stars":{"1":{"who":"코그","text":"확보 실패! 상자 대부분이 파손되었습니다!"},"2":{"who":"코그","text":"확보! 상자 하나가 연방 쪽에 넘어갔습니다!"},"3":{"who":"코그","text":"보급 대성공! 상자 5개 전부 확보!"}}},{"id":"M4-4","no":4,"title":"아네트의 대성당","boss":false,"before":[{"who":"아네트","text":"(대성당 첨탑 위에서) 제국 여러분, 연방 정화 빔 첨탑에 접근하셨습니다. 입장은 예약제입니다."},{"who":"이그니스","text":"전투 중에 예약제를 적용하냐."},{"who":"아네트","text":"상담소 규정입니다. 빔 한 발에 정화 한 건. 대기 번호를 뽑아 주세요."},{"who":"코그","text":"대단한 장비입니다! 해체하고 싶습니다!"},{"who":"베르단","text":"해체는 후에 하라."},{"who":"로제","text":"아네트 씨를 본 적이 있는 것 같은데, 연방 의무 동료인가요."},{"who":"아네트","text":"로제 선배님, 오랜만입니다. 차트를 가져왔습니다."}],"after":[{"who":"아네트","text":"(첨탑 위에서) 빔 출력 70%로 마무리하겠습니다. 전원 포획 대신 안내를 드리겠습니다."},{"who":"코그","text":"안내는 정화방 입구입니다!"},{"who":"로제","text":"후배의 솜씨가 훌륭해서 눈물이 나네요."}],"stars":{"1":{"who":"코그","text":"돌파 지연! 빔의 아름다움에 눈이 팔렸습니다!"},"2":{"who":"코그","text":"돌파! 빔에 맞은 병사 여럿이 행복한 얼굴로 쓰러졌습니다!"},"3":{"who":"코그","text":"첨탑 돌파! 빔 피격 0, 아네트 씨 인사 완료!"}}},{"id":"M4-5","no":5,"title":"자하라의 흥정","boss":false,"before":[{"who":"자하라","text":"안녕하세요, 제국 여러분. 또 뵙네요. 이번엔 대성당 안에 있는 연방 상인으로서 입장료를 받습니다."},{"who":"이그니스","text":"입장료를 또 받냐."},{"who":"자하라","text":"장사입니다. 그런데 이번엔 꼬리가 말려서 움직임이 둔합니다. 제가 불리하군요."},{"who":"코그","text":"개조 그물 발사!"},{"who":"자하라","text":"이번엔 걸렸네요. 흥정할까요. 저를 풀어 주시면 금화 100닢을 드리겠습니다."},{"who":"베르단","text":"거절한다."},{"who":"자하라","text":"200닢."}],"after":[{"who":"자하라","text":"졌습니다. 포획 조항이 계약서에 없으니 협상해야 하는데요. 정화방 이용 요금은 월정액이죠?"},{"who":"로제","text":"월정액입니다."},{"who":"자하라","text":"월정액이면 이득이네요. 합류하겠습니다. 단, 월말 정산 때 이용 횟수 할인을 요구합니다."},{"who":"이그니스","text":"이용 횟수 할인이라니, 이용 횟수가 늘수록 이득이라는 얘기구만."}],"stars":{"1":{"who":"코그","text":"합류했는데 계약서 문구가 모호합니다!"},"2":{"who":"코그","text":"합류! 요금 협상이 길어졌습니다!"},"3":{"who":"코그","text":"자하라 씨 합류! 월정액 계약 체결!"}}},{"id":"M4-6","no":6,"title":"세뇌된 전우","boss":false,"before":[{"who":"코그","text":"연방 진영에서 두 사람이 나왔습니다! 제국 출신 렌 중위와 카이단 씨!"},{"who":"이그니스","text":"렌! 카이단! 정신 차려라! 너희는 제국군이다!"},{"who":"렌","text":"나는 연방의 노예다. 이것은 신념이 아니라 몸이 먼저 간 결과일 뿐이다."},{"who":"카이단","text":"주인님이 부르셨어요! 이그니스 상사님, 미안해요, 꼬리가 말을 안 들어요!"},{"who":"베르단","text":"세뇌가 깊다. 정화로 풀 수는 없다."},{"who":"로제","text":"저는 이쪽이 더 부럽네요. 세뇌 상태 속도가 훌륭합니다."}],"after":[{"who":"렌","text":"…후퇴한다. 몸이 먼저 갔을 뿐이다."},{"who":"카이단","text":"이그니스 상사님, 다음에 또 만나요! 꼬리 흔들면서!"},{"who":"이그니스","text":"세뇌당한 놈이 저렇게 행복한 얼굴을 하다니."},{"who":"베르단","text":"다음 전투에서 되찾는다."}],"stars":{"1":{"who":"코그","text":"격퇴 지연! 렌 중위가 전술적으로 안전한 거리를 유지했습니다!"},"2":{"who":"코그","text":"격퇴! 카이단 씨가 이그니스 상사님 손을 핥으려 했습니다!"},"3":{"who":"코그","text":"전우 격퇴! 렌 중위 도주, 카이단 씨 꼬리 반응 측정 완료!"}}},{"id":"M4-7","no":7,"title":"폐허의 야식","boss":false,"before":[{"who":"로제","text":"야식 시간입니다. 폐허 한가운데서 컵라면 드릴게요."},{"who":"핀","text":"컵라면이라니, 전투 중에 먹냐."},{"who":"벨루가","text":"나는 곱빼기!"},{"who":"자하라","text":"컵라면 한 컵에 금화 2닢입니다. 노예 할인 적용해서 1닢."},{"who":"이그니스","text":"노예 할인이 있구만."},{"who":"베르단","text":"장군도 할인 대상인가."},{"who":"자하라","text":"대상입니다. 단, 서비스 시간 후에는 추가 요금이 붙습니다."}],"after":[{"who":"코그","text":"야식 만족도 5점 만점!"},{"who":"핀","text":"국물이 따뜻해서 기분이 좋아졌어. …분명 국물 때문이야."},{"who":"로제","text":"국물이 좋긴 하죠."}],"stars":{"1":{"who":"코그","text":"야식 중단! 연방 병사가 컵라면을 훔쳐 갔습니다!"},"2":{"who":"코그","text":"성공! 벨루가 씨가 곱빼기 두 컵을 드셨습니다!"},"3":{"who":"코그","text":"야식 대성공! 컵라면 재고 소진!"}}},{"id":"M4-8","no":8,"title":"로나의 방어선","boss":false,"before":[{"who":"로나","text":"(연방 장교) 제국의 주인들, 이 방어선은 제가 지킵니다. 방어선 너머는 연방 상담소 구역입니다."},{"who":"그로크","text":"로나 교관님! 오늘도 평가는 하로 부탁드립니다!"},{"who":"오그","text":"대장!!! 어디 가시는 겁니까!!! 우리 오크 용병대는 제국 소속이라구요!!!"},{"who":"그로크","text":"나는 이제 연방 소속이다. 로나 교관님의 조련을 받는 중이다."},{"who":"이그니스","text":"대장이 연방으로 넘어갔구만."},{"who":"오그","text":"오크 여성 좀 잡아 달라구요!!! 대장이 없으면 누가 해요!!!"}],"after":[{"who":"로나","text":"방어선은 오늘까지입니다. 오크 용병대 여러분, 반성문 5장씩."},{"who":"오그","text":"5장씩이라니! 대장님은 6장 쓰셨다던데!"},{"who":"그로크","text":"6장째는 선물이다. 받아라."},{"who":"로나","text":"접수합니다."}],"stars":{"1":{"who":"코그","text":"돌파 지연! 오크 용병대가 대장을 되찾으려 했습니다!"},"2":{"who":"코그","text":"돌파! 그로크 대장이 끝까지 로나 교관을 따라다녔습니다!"},"3":{"who":"코그","text":"방어선 돌파! 오크 용병대 반성문 접수 완료!"}}},{"id":"M4-9","no":9,"title":"베르단 친위대","boss":false,"before":[{"who":"베르단","text":"친위대는 나를 따르라. 오늘은 대성당 중심부로 진입한다."},{"who":"친위대원","text":"장군님, 저희 족쇄 점검 시간입니다! 먼저 해도 되겠습니까!"},{"who":"베르단","text":"점검 시간은 전투 후다."},{"who":"친위대원","text":"지금이 아니면 안 됩니다! 장력이 헐겁습니다!"},{"who":"이그니스","text":"친위대도 노예 못지않구만."},{"who":"베르단","text":"규정집을 읽어라. 점검은 월례다."}],"after":[{"who":"베르단","text":"점검을 시작한다. 장력 확인."},{"who":"친위대원","text":"감사합니다! 장군님의 확인이면 안심됩니다!"},{"who":"로제","text":"친위대원 전원 만족도 최상이네요."}],"stars":{"1":{"who":"코그","text":"점검 지연! 대원들이 줄을 서서 기다립니다!"},"2":{"who":"코그","text":"점검 양호! 일부 대원이 장군님께 직접 점검을 요청했습니다!"},"3":{"who":"코그","text":"친위대 점검 완료! 장력 전원 합격!"}}},{"id":"M4-10","no":10,"title":"정화 빔 첨탑 대성당 기체","boss":true,"before":[{"who":"아네트","text":"(성당 기체 위에서) 제국 여러분, 본 기체는 정화 빔 첨탑 대성당 기체입니다. 일제 정화를 시작하겠습니다."},{"who":"코그","text":"대단합니다! 빔이 사방으로 퍼집니다!"},{"who":"이그니스","text":"빔에 맞으면 어떻게 되냐."},{"who":"로제","text":"행복해집니다."},{"who":"베르단","text":"행복해지면 전투가 안 된다. 접근해서 파괴한다."},{"who":"핀","text":"행복해지는 건 싫어! …아니 전투 때문에!"}],"after":[{"who":"아네트","text":"기체가 파괴되었습니다. 오늘 상담은 여기까지입니다."},{"who":"로제","text":"후배님, 수고했어요."},{"who":"베르단","text":"4장 종료다. 대성당을 점령했다."},{"who":"코그","text":"빔 장비 해체 완료! 다음 전투에서 써 보고 싶습니다!"}],"stars":{"1":{"who":"코그","text":"반파! 빔이 사방으로 퍼져 도심에 분홍빛이 드리웠습니다!"},"2":{"who":"코그","text":"파괴! 빔에 맞은 병사들이 행복하게 쓰러졌습니다!"},"3":{"who":"코그","text":"대성당 기체 파괴! 빔 장비 확보!"}}}]},"M5":{"chapter":"M5","title":"강철 군주의 결단","line":"male","episodes":[{"id":"M5-1","no":1,"title":"총공세의 아침, 거꾸로 콜","boss":false,"before":[{"who":"로제·핀·벨루가·자하라","text":"오늘도 어김없이…… 정화 시퀀스다!! 긴장하는 게 좋을 거예요, 주인님들!!!"},{"who":"이그니스","text":"…그건 내 대사다."},{"who":"핀","text":"내가 먼저 외친 거야. 불평하지 마."},{"who":"베르단","text":"노예가 먼저 콜하는 것은 규정 위반이 아니다. 제17조, 「콜은 선착순」이다."},{"who":"이그니스","text":"그런 조항이 있었나."},{"who":"코그","text":"어제 제가 추가했습니다!"},{"who":"자하라","text":"선착순이면 이득이네요."}],"after":[{"who":"코그","text":"총공세 첫 방어 성공! 병사 45명 포획!"},{"who":"이그니스","text":"콜에서 밀린 주인이 전투에서는 이기는구만."},{"who":"로제","text":"콜은 노예의 몫, 전투는 주인의 몫이죠."}],"stars":{"1":{"who":"코그","text":"방어 지연! 콜 순서 다툼이 있었습니다!"},"2":{"who":"코그","text":"방어 성공! 이그니스 상사님이 콜에서 밀리셨습니다!"},"3":{"who":"코그","text":"첫 방어 대성공! 콜 호응도 폭발!"}}},{"id":"M5-2","no":2,"title":"전선이 흔들린다","boss":false,"before":[{"who":"베르단","text":"연방 주력 부대가 평원에 집결했다. 사기가 높다."},{"who":"연방 병사","text":"우리는 제국을 정복한다! 포획되면 간식을 준다고 들었다!"},{"who":"이그니스","text":"우리 쪽도 간식이 있다는 소문이 퍼졌구만."},{"who":"로제","text":"간식은 사실입니다. 포획 후 바로 지급됩니다."},{"who":"연방 병사","text":"정말로 간식이다! 포획해 달라!"},{"who":"베르단","text":"포획을 부탁하는 적은 처음 본다."}],"after":[{"who":"코그","text":"전선 정리 완료! 간식 재고 소진!"},{"who":"이그니스","text":"전쟁이 아니라 야유회구만."},{"who":"핀","text":"나는 야유회에서 불평하는 게 일이야."}],"stars":{"1":{"who":"코그","text":"정리 지연! 간식 줄이 평원을 가로지릅니다!"},"2":{"who":"코그","text":"정리 양호! 간식이 부족해서 눈물 흘린 병사가 있습니다!"},"3":{"who":"코그","text":"전선 정리! 간식 재고 완벽 배분!"}}},{"id":"M5-3","no":3,"title":"자하라의 마지막 흥정","boss":false,"before":[{"who":"자하라","text":"제국 여러분, 사령부에 보급품을 납품하러 왔습니다. 가격은 시가의 반값입니다."},{"who":"이그니스","text":"반값이면 의심스럽구만."},{"who":"자하라","text":"월정액 구독자 할인입니다. 저는 정화방 월정액 구독자니까요."},{"who":"베르단","text":"구독자 할인이 군수품에도 적용되는가."},{"who":"자하라","text":"적용됩니다. 대신 정화방 이용 횟수를 두 배로 해 주세요."},{"who":"코그","text":"그건 협상 불가입니다! …아니 협상 가능합니다!"}],"after":[{"who":"자하라","text":"계약 완료. 이용 횟수는 두 배로, 요금은 반값."},{"who":"이그니스","text":"상인이 이기는 구조구만."},{"who":"자하라","text":"이득이 되는 거래만 합니다."}],"stars":{"1":{"who":"코그","text":"계약 보류! 협상이 길어졌습니다!"},"2":{"who":"코그","text":"계약 체결! 자하라 씨가 추가 조항을 요구했습니다!"},"3":{"who":"코그","text":"납품 계약 체결! 이용 횟수 두 배!"}}},{"id":"M5-4","no":4,"title":"핀의 자진 대기","boss":false,"before":[{"who":"핀","text":"(정화방 앞에서 번호표를 들고) 오늘은 내가 먼저 줄 섰어. 가장 앞줄이야."},{"who":"로제","text":"어머, 핀 씨가 자진해서 줄 서시다니."},{"who":"핀","text":"자진한 거 아니야! 앞줄에 서야 불평을 더 빨리 할 수 있으니까!"},{"who":"벨루가","text":"그럼 나도 앞줄! 하늘에서 줄 서도 되지?"},{"who":"이그니스","text":"하늘에서 줄 서는 건 처음 보는구만."}],"after":[{"who":"핀","text":"불평 끝. …기분이 좋아졌어. 불평 때문이야."},{"who":"로제","text":"핀 씨, 이제 불평과 칭찬의 경계가 없어지고 있어요."},{"who":"핀","text":"경계가 없어진 게 아니라 내가 넓어진 거야."}],"stars":{"1":{"who":"코그","text":"대기 불안정! 핀 씨가 순서를 착각하고 뒷줄에 서셨습니다!"},"2":{"who":"코그","text":"대기 성공! 불평 시간이 9분으로 늘었습니다!"},"3":{"who":"코그","text":"핀 씨 자진 대기 성공! 불평 시간 5분!"}}},{"id":"M5-5","no":5,"title":"구속 대전","boss":false,"before":[{"who":"베르단","text":"이번 전투는 「구속 대전」이다. 쌍방이 서로를 묶는 방식이다."},{"who":"코그","text":"대단한 전술입니다! 전원 묶이면 아무도 못 움직입니다!"},{"who":"이그니스","text":"그게 목적이라니, 이건 전술이 아니라 취향이구만."},{"who":"연방 병사","text":"우리도 구속 대전에 참가한다! 묶일 준비 완료!"},{"who":"제국 병사","text":"우리도다! 묶이러 달려간다!"}],"after":[{"who":"연방 병사","text":"(묶인 채로) 이기고 있는지 지고 있는지 모르겠지만 행복하다."},{"who":"제국 병사","text":"(묶인 채로) 저도 마찬가지다."},{"who":"로제","text":"승패 판정은 코그 씨가 맡으시죠."},{"who":"코그","text":"쌍방 승리입니다!"}],"stars":{"1":{"who":"코그","text":"판정 불가! 쌍방 모두 즐거워서 기록이 어렵습니다!"},"2":{"who":"코그","text":"성공! 일부 병사가 묶인 채로 잠들었습니다!"},"3":{"who":"코그","text":"구속 대전 대성공! 쌍방 만족도 100%!"}}},{"id":"M5-6","no":6,"title":"이그니스의 변화","boss":false,"before":[{"who":"이그니스","text":"오늘 정화 시퀀스는 평소처럼 하겠다. 로제, 오늘 일정표를."},{"who":"로제","text":"이그니스 상사님, 오늘은 담담하시네요."},{"who":"이그니스","text":"당황은 이제 필요 없구만. 업무다. 업무."},{"who":"핀","text":"이그니스 상사가 당황하지 않는 건 재미없어."},{"who":"이그니스","text":"재미는 업무에 포함되지 않는다."},{"who":"벨루가","text":"그래도 얼굴이 약간 빨개졌는데!"},{"who":"이그니스","text":"이건 용광로 열기다."}],"after":[{"who":"이그니스","text":"일정 종료. 보고서 제출."},{"who":"코그","text":"상사님이 보고서를 쓰시다니! 내용이 궁금합니다!"},{"who":"이그니스","text":"기밀이다."}],"stars":{"1":{"who":"코그","text":"일정 지연! 이그니스 상사님이 중간에 얼굴이 빨개졌습니다!"},"2":{"who":"코그","text":"일정 양호! 보고서에 얼룩이 한 점 보입니다!"},"3":{"who":"코그","text":"일정 완벽! 이그니스 상사님 업무 어조 100%!"}}},{"id":"M5-7","no":7,"title":"루시안의 합류","boss":false,"before":[{"who":"코그","text":"연방에서 엘프 한 분이 이쪽으로 넘어왔습니다! 근위대장 루시안 씨!"},{"who":"루시안","text":"제국 여러분, 연방에서 해방된 동포라고 극진히 환영해 주셔서 감사합니다. 다만 한 가지 불편한 점이 있습니다."},{"who":"베르단","text":"말하라."},{"who":"루시안","text":"목줄이 없습니다. 연방 시절에는 항상 착용했는데, 지금은 목이 허전해서 힘듭니다."},{"who":"이그니스","text":"목줄을 달라는 놈은 처음 보는구만."},{"who":"루시안","text":"모범 노예로서의 습관입니다."}],"after":[{"who":"코그","text":"개조 목줄 제작 완료! 루시안 씨, 착용해 보세요!"},{"who":"루시안","text":"(착용) …딱 맞습니다. 감사합니다. 이제 편안히 일할 수 있습니다."},{"who":"베르단","text":"루시안을 주인 팀에 편입한다. 마도사의 역할은 지원이다."},{"who":"루시안","text":"주인이 되는 것은 처음이라 어색합니다만, 모범 주인이 되겠습니다."}],"stars":{"1":{"who":"코그","text":"합류! 루시안 씨가 목줄을 두 개 요청하셨습니다!"},"2":{"who":"코그","text":"합류! 루시안 씨가 주인 역할에 어색해하십니다!"},"3":{"who":"코그","text":"루시안 씨 합류! 개조 목줄 만족도 최상!"}}},{"id":"M5-8","no":8,"title":"셀렌의 분노","boss":false,"before":[{"who":"셀렌","text":"(연방 마도사) 루시안! 당신이 제국으로 넘어갔다는 소문이 사실이었군요!"},{"who":"루시안","text":"셀렌. 오랜만입니다. 동료와 싸우고 싶지는 않습니다."},{"who":"셀렌","text":"모범 노예였던 당신이 어떻게 주인이 될 수 있나요!"},{"who":"루시안","text":"규정집을 읽어 보면 자격 조건에 「본인의 의지」가 있습니다."},{"who":"셀렌","text":"본인의 의지라니…… 그건 제 꿈이기도 했는데!"},{"who":"이그니스","text":"꿈이 뭐냐."},{"who":"셀렌","text":"주인이 되는 거예요. …아니, 노예인 채로 주인도 되는 거요."}],"after":[{"who":"셀렌","text":"…졌습니다. 하지만 분하지 않습니다. 오히려 후련합니다."},{"who":"루시안","text":"셀렌, 이쪽으로 오시겠습니까. 제국 쪽 규정집은 더 유연합니다."},{"who":"셀렌","text":"생각해 보겠습니다. 다만 오늘은 돌아가야 합니다."},{"who":"베르단","text":"다음에 만나자."}],"stars":{"1":{"who":"코그","text":"격퇴 지연! 규정집 해석 논쟁이 길어졌습니다!"},"2":{"who":"코그","text":"격퇴! 셀렌 씨의 눈이 약간 촉촉했습니다!"},"3":{"who":"코그","text":"셀렌 씨 격퇴! 규정집 대화 성공!"}}},{"id":"M5-9","no":9,"title":"전야의 거꾸로 점검","boss":false,"before":[{"who":"로제","text":"오늘은 제가 주인님들의 족쇄를 점검할게요."},{"who":"이그니스","text":"노예가 주인을 점검하다니."},{"who":"로제","text":"역할 교대입니다. 규정집 제18조."},{"who":"핀","text":"나도 점검해 볼래. 이그니스 상사의 장력은 어디 보자."},{"who":"이그니스","text":"만지지 마라. 아니, 만져도 된다."},{"who":"벨루가","text":"나는 베르단 장군님을 점검!"},{"who":"베르단","text":"점검은 존중하며 하라."}],"after":[{"who":"코그","text":"점검 완료! 전원 장력 98%!"},{"who":"루시안","text":"어느 쪽이 주인이고 어느 쪽이 노예인지 모호해졌습니다."},{"who":"로제","text":"모호해야 평화롭죠."}],"stars":{"1":{"who":"코그","text":"점검 혼란! 아무도 누가 주인인지 모릅니다!"},"2":{"who":"코그","text":"점검 양호! 역할이 뒤섞였습니다!"},"3":{"who":"코그","text":"거꾸로 점검 대성공! 장력 전원 합격!"}}},{"id":"M5-10","no":10,"title":"총사령관 클레어 기체","boss":true,"before":[{"who":"클레어","text":"(기체 위에서) 제국 총사령관 베르단 장군님, 홍차를 준비했습니다. 전투 후에 드시죠."},{"who":"베르단","text":"연방 총사령관 클레어. 귀하의 족쇄 규정 개정안이 감동적이었다."},{"who":"클레어","text":"귀하의 3미터 규정 개정안도 훌륭했습니다."},{"who":"이그니스","text":"사령관 둘이 칭찬만 하고 있구만."},{"who":"코그","text":"구속 대전 개시 신호를 보내겠습니다!"},{"who":"연방·제국 병사","text":"(전원 자진해서 묶이러 달려간다)"},{"who":"로제","text":"전선이 흔들립니다. 양쪽 모두 기뻐서."}],"after":[{"who":"클레어","text":"졌습니다. 훌륭한 승부였어요."},{"who":"베르단","text":"귀하도 훌륭했다. 홍차는 여기서 마시겠다."},{"who":"로제","text":"하늘을 보세요. 분홍빛 균열이 보입니다."},{"who":"베르단","text":"…정체를 알 수 없는 빛이다. 경계 태세를 유지한다."},{"who":"이그니스","text":"5장 종료구만. 아직 끝이 아닌 것 같다."},{"who":"핀","text":"하늘이 갈라졌어. …왠지 설렌다."}],"stars":{"1":{"who":"코그","text":"반파! 균열의 정체를 파악하지 못했습니다!"},"2":{"who":"코그","text":"격파! 균열이 일시적으로 확대되었습니다!"},"3":{"who":"코그","text":"클레어 기체 격파! 쌍방 병사 만족도 최상, 상공 균열 관측!"}}}]},"C11":{"chapter":"C11","title":"마계","line":"demon","episodes":[{"id":"C11-1","no":1,"title":"균열의 문","boss":false,"before":[{"who":"클레어","text":"분홍빛 균열이 마계의 문으로 열렸습니다. 베르단 장군, 임시 휴전을 제안드립니다."},{"who":"베르단","text":"받아들이겠다. 정중한 문서로 서명하자."},{"who":"클레어","text":"휴전 협정서입니다. 제3조 「족쇄 규정은 양측 규정집을 병기한다」."},{"who":"베르단","text":"병기하는 것은 좋으나 서명 위치가 문제다. 「서명자의 가장 잡기 편한 위치」."},{"who":"클레어","text":"…문서 위치입니다. 오해 없으시길."},{"who":"몽마 병사","text":"(문 너머에서) 어서 오세요! 환영합니다! 입장은 예약제입니다!"}],"after":[{"who":"베르단","text":"문 앞 병력 격퇴. 양국 연합군이 정식으로 결성되었다."},{"who":"클레어","text":"연합 이름은 「정화 연합」으로 하죠. 상표는 이미 등록했습니다."},{"who":"베르단","text":"상표는 우리가 먼저였다."},{"who":"클레어","text":"연합 결성 후에 다투기로 합시다."}],"stars":{"1":{"who":"클레어","text":"결성은 했으나 상표 분쟁이 이어집니다."},"2":{"who":"베르단","text":"연합 결성. 서명 위치에 대한 이견이 있었다."},"3":{"who":"클레어","text":"연합 결성 완벽. 서명 위치 분쟁 없음."}}},{"id":"C11-2","no":2,"title":"마계 입국 심사","boss":false,"before":[{"who":"몽마 병사","text":"마계에 오신 것을 환영합니다. 입국 목적을 말씀해 주세요."},{"who":"클레어","text":"정화입니다."},{"who":"몽마 병사","text":"정화는 저희도 환영합니다. 방문 기간은?"},{"who":"베르단","text":"원인이 해결될 때까지다."},{"who":"몽마 병사","text":"원인이라니, 무슨 원인이요?"},{"who":"클레어","text":"곧 알게 되겠죠. 입국 도장 부탁드립니다."},{"who":"몽마 병사","text":"도장은 이쪽입니다. 분홍색입니다."}],"after":[{"who":"몽마 병사","text":"입국 심사 통과! 근데 왜 전투가 되었죠?"},{"who":"베르단","text":"도장 찍는 과정에서 저항했기 때문이다."},{"who":"몽마 병사","text":"저항이라니, 저는 원래 도장 찍는 직원입니다."},{"who":"클레어","text":"실례했습니다. 사과 홍차를 드리겠습니다."}],"stars":{"1":{"who":"클레어","text":"심사 지연. 직원의 질문이 길었습니다."},"2":{"who":"베르단","text":"심사 통과. 도장이 일부 번졌다."},"3":{"who":"클레어","text":"입국 심사 완료. 도장 색상 분홍."}}},{"id":"C11-3","no":3,"title":"몽마 병사의 정체","boss":false,"before":[{"who":"몽마 병사","text":"저는 최하급 몽마입니다. 마계 방위를 맡고 있습니다. 근데 방위가 처음이라서요."},{"who":"베르단","text":"방위 경험이 없는 병사가 어떻게 방어하나."},{"who":"몽마 병사","text":"방어는 안 하고 환영합니다. 방어라는 걸 배운 적이 없어요."},{"who":"클레어","text":"환영하는 병사를 상대하는 것은 처음입니다."},{"who":"몽마 병사","text":"사실 우리 마계 병사들은 전부 구직자 출신이에요. 여왕님이 월급을 안 주셔서."}],"after":[{"who":"클레어","text":"병사 전원 제압. 하지만 이분들은 적이 아니라 노동자입니다."},{"who":"베르단","text":"노동자 대우를 개선해 주면 협조할 것이다."},{"who":"몽마 병사","text":"월급 대신 정화를 받으면 안 될까요? 간식 포함으로요."},{"who":"클레어","text":"협상하죠."}],"stars":{"1":{"who":"클레어","text":"확보 지연. 병사들이 일하기 싫어합니다."},"2":{"who":"베르단","text":"협조 확보. 정화 대기 줄이 길어졌다."},"3":{"who":"클레어","text":"병사 전원 협조 확보. 월급 협상 시작."}}},{"id":"C11-4","no":4,"title":"누가 누구를 정화하나","boss":false,"before":[{"who":"클레어","text":"몽마 병사 정화는 연방 규정에 따라 제가 합니다."},{"who":"베르단","text":"정화는 제국 규정이 우선이다. 내가 한다."},{"who":"클레어","text":"우선 규정은 병기하기로 했습니다."},{"who":"베르단","text":"병기하면 두 규정이 충돌한다. 주인과 노예의 소유권도 어느 쪽에 귀속되는가."},{"who":"몽마 병사","text":"저는 어느 쪽이든 괜찮은데요. 줄 서면 되죠?"},{"who":"클레어","text":"줄은 한 줄로 세우겠습니다."}],"after":[{"who":"베르단","text":"소유권은 병사 본인의 선택에 따르기로 했다."},{"who":"클레어","text":"선택제. 합리적이네요. 병사 여러분, 마음에 드는 주인 앞에 서세요."},{"who":"몽마 병사","text":"(전원 두 줄로 나뉜다) 어, 균형이 맞네요."},{"who":"베르단","text":"문제없다."}],"stars":{"1":{"who":"클레어","text":"해결 지연. 규정 해석이 갈렸습니다."},"2":{"who":"베르단","text":"해결. 일부 병사가 두 줄 모두에 섰다."},"3":{"who":"클레어","text":"소유권 분쟁 해결. 선택제 도입."}}},{"id":"C11-5","no":5,"title":"마계 식당","boss":false,"before":[{"who":"몽마 병사","text":"마계 식당입니다. 오늘의 메뉴는 정기 스프와 분홍 파스타입니다."},{"who":"클레어","text":"정기 스프라니, 이름이 수상한데요."},{"who":"몽마 병사","text":"이름만 그렇고 평범한 닭고기 스프예요."},{"who":"베르단","text":"분홍 파스타는 매운가."},{"who":"몽마 병사","text":"달아요. 딸기 소스입니다."},{"who":"클레어","text":"식사 후 정화 구역으로 이동하죠."}],"after":[{"who":"몽마 병사","text":"후식은 마계 푸딩입니다. 아주 쫀득해요."},{"who":"클레어","text":"쫀득함은 대단히 중요한 요소입니다."},{"who":"베르단","text":"레시피를 확보하라."},{"who":"몽마 병사","text":"레시피는 여왕님만 아십니다."}],"stars":{"1":{"who":"클레어","text":"식사 중단. 파스타가 식었습니다."},"2":{"who":"베르단","text":"식사 양호. 푸딩 쟁탈전이 있었다."},"3":{"who":"클레어","text":"식사 완료. 후식 만족도 최상."}}},{"id":"C11-6","no":6,"title":"마계 사무소","boss":false,"before":[{"who":"몽마 병사","text":"이쪽은 마계 사무소입니다. 여왕님 면담 신청서는 이쪽에서 받습니다."},{"who":"베르단","text":"면담 신청서를 작성하겠다."},{"who":"클레어","text":"면담 사유는 「원인 규명 및 정화 협의」로 적죠."},{"who":"몽마 병사","text":"접수했습니다. 다만 대기 번호가 3,000번입니다."},{"who":"클레어","text":"3,000번이라니, 마계에서도 예약이 밀리는군요."},{"who":"베르단","text":"새치기는 허락되지 않는다. 하지만 전투는 허락된다."}],"after":[{"who":"몽마 병사","text":"여왕님께서 직접 나오신답니다. 번호표는 필요 없다고 하십니다."},{"who":"클레어","text":"직접 나오신다니, 준비하겠습니다."},{"who":"베르단","text":"연합군 전원 정비하라."}],"stars":{"1":{"who":"클레어","text":"확보 지연. 사무소가 혼잡했습니다."},"2":{"who":"베르단","text":"면담 확보. 일부 병사가 번호표를 버리지 않았다."},"3":{"who":"클레어","text":"여왕 면담 확보. 연합군 사기 최고조."}}},{"id":"C11-7","no":7,"title":"비밀 공개, 첫 번째","boss":false,"before":[{"who":"여왕","text":"(등장) 어서 오세요. 마계의 여왕입니다. 모두가 궁금해하시는 원인에 대해 설명드리겠습니다."},{"who":"클레어","text":"원인을 아십니까."},{"who":"여왕","text":"알다마다요. 제가 원인이거든요."},{"who":"베르단","text":"…뭐라고."},{"who":"여왕","text":"말씀드리자면 이렇습니다. 선임 마왕께서는 연로하셨고, 제 이력서를 보시고 그 자리에서 면접 겸 시연을 요청하셨어요."},{"who":"클레어","text":"시연이라 함은."},{"who":"여왕","text":"말씀드리기 부끄러운 내용이라 생략하겠습니다. 결론만 말씀드리면 시연이 너무 훌륭해서 선임 마왕께서 그만 복상사하셨습니다."}],"after":[{"who":"여왕","text":"오해 마세요. 호흡 문제였습니다. 저는 최선을 다했을 뿐이에요."},{"who":"베르단","text":"호흡 문제로 복상사한다는 건 일반적이지 않은 표현이다."},{"who":"여왕","text":"일반적이지 않죠. 하지만 사실입니다."},{"who":"클레어","text":"이야기를 이어 주세요."}],"stars":{"1":{"who":"클레어","text":"공개 지연. 여왕이 시연 장면을 상세히 설명하려 했습니다."},"2":{"who":"베르단","text":"공개 양호. 이야기가 샛길로 샜다."},"3":{"who":"클레어","text":"첫 공개 성공. 여왕의 면접 경위 확보."}}},{"id":"C11-8","no":8,"title":"비밀 공개, 두 번째","boss":false,"before":[{"who":"여왕","text":"그 정기를 제가 얼떨결에 흡수해서 마왕이 되었습니다. 취임 첫날 설정을 시험해 보다가 문제가 생겼어요."},{"who":"클레어","text":"설정이라고요."},{"who":"여왕","text":"「세상 모든 종족의 성향 설정」 화면이 있었는데, 재미있게 하려고 모두 S로 바꿨습니다. 그리고 해제 버튼을 못 찾았습니다."},{"who":"베르단","text":"…사용 설명서는 읽지 않았나."},{"who":"여왕","text":"읽는 데 3,000쪽이 필요했습니다. 읽지 못했어요."},{"who":"클레어","text":"그래서 세상이 모두 S가 되었군요."}],"after":[{"who":"여왕","text":"잡혀서 고문당하면 M이 된다는 건 제가 정한 게 아니에요. 설정이 저절로 균형을 잡은 것 같습니다."},{"who":"베르단","text":"균형이 맞은 것 자체가 기적이다."},{"who":"여왕","text":"덕분에 종족 번식도 끊기지 않았죠. 저의 실수가 세상을 구했다고 봅니다."},{"who":"클레어","text":"실수가 구했다는 말은 위험한 표현입니다."}],"stars":{"1":{"who":"클레어","text":"확보 지연. 여왕이 사용 설명서 이야기를 반복했습니다."},"2":{"who":"베르단","text":"원인 확보. 여왕의 변명이 길었다."},"3":{"who":"클레어","text":"원인 확보. 설정 화면 실수 기록 완료."}}},{"id":"C11-9","no":9,"title":"코어의 정체","boss":false,"before":[{"who":"클레어","text":"하늘의 분홍빛 균열은 무엇입니까."},{"who":"여왕","text":"그건 제 방의 환기구입니다. 문의 열쇠를 겸하고 있어요."},{"who":"베르단","text":"환기구가 세계에 균열을 일으키나."},{"who":"여왕","text":"코어가 과열되면 열립니다. 코어를 파괴하면 문이 닫히고 저주는 해제되지 않지만 평화로워집니다."},{"who":"클레어","text":"저주는 해제되지 않나요."},{"who":"여왕","text":"저도 해제하는 방법을 몰라요. 다만 여러분은 이미 즐기고 계시잖아요."}],"after":[{"who":"베르단","text":"반박의 여지가 없다."},{"who":"클레어","text":"코어를 파괴하죠. 정중하게."},{"who":"여왕","text":"파괴 전에 홍차 한 잔 드시겠어요?"},{"who":"클레어","text":"파괴 후에 마시겠습니다."}],"stars":{"1":{"who":"클레어","text":"확보 지연. 여왕이 코어 보호를 시도했습니다."},"2":{"who":"베르단","text":"확보. 환기구 열쇠 설명이 장황했다."},"3":{"who":"클레어","text":"코어 위치 확보. 여왕의 협조적 태도 확인."}}},{"id":"C11-10","no":10,"title":"서큐버스 여왕","boss":true,"before":[{"who":"여왕","text":"여러분, 최종 시연을 시작하겠습니다. 오늘 시연은 저의 마지막 쇼입니다."},{"who":"클레어","text":"정중하게 상대해 드리겠습니다."},{"who":"베르단","text":"연합군 전원, 구속 대전 개시."},{"who":"여왕","text":"구속 대전이라니, 저를 묶으시려고요? 좋은 취향이시네요."},{"who":"몽마 병사","text":"여왕님을 응원합니다! 하지만 구속당하시길 기대합니다!"},{"who":"여왕","text":"병사들이 배신하다니, 감동적이네요."}],"after":[{"who":"여왕","text":"졌습니다. 완패입니다. 여러분의 정화는 훌륭해요."},{"who":"클레어","text":"코어를 파괴했습니다. 문이 닫힙니다."},{"who":"여왕","text":"문이 닫히면 저희는 이제 무엇을 해야 하나요. 월급도 없는데."},{"who":"베르단","text":"전원 연방·제국 소속 영웅들의 노예로 편입한다. 월급 대신 정화를 지급한다."},{"who":"몽마 병사","text":"감사합니다! 저희 서큐버스·인큐버스 전원 신청서를 제출합니다!"},{"who":"여왕","text":"제 신청서가 제일 먼저 접수되어야 합니다. 1번입니다."},{"who":"클레어","text":"1번은 저입니다. 아니, 신청서 번호가 1번이라는 뜻입니다."},{"who":"베르단","text":"서열을 정하자."},{"who":"여왕","text":"(영웅들을 향해 일렬로 서며) 전원, 함께 외치시죠."},{"who":"모두","text":"오늘도 어김없이…… 정화 시퀀스다!! 긴장하는 게 좋을 거다, 노예들아!!!"},{"who":"서큐버스·인큐버스 전원","text":"네~~~~~~~~!! (하트 뿅뿅)"},{"who":"클레어","text":"11장 종료. 평화로운 해결입니다."}],"stars":{"1":{"who":"클레어","text":"여왕 도주 후 재접수. 코어 파괴는 성공했습니다."},"2":{"who":"베르단","text":"여왕 포획. 신청서 번호 분쟁이 이어진다."},"3":{"who":"클레어","text":"여왕 포획. 신청서 1번 접수, 전원 노예 편입 완료."}}}]},"C11_reactions":{"클레어":["홍차는 식기 전에 마시고, 정화는 식기 전에 시작합니다.","마계도 서식은 같네요. 좋은 점입니다."],"그레타":["두들겨 고치는 건 여기서도 통하는구만.","여왕이 순번표를 뽑는 건 처음 본다니까."],"실비아":["정중하게 말씀드립니다. 마계 병사의 허리띠를 조준하겠습니다.","허락하신다면 여왕님의 채찍 소리를 한 번 듣고 싶습니다."],"아네트":["마계 상담소도 예약제입니다. 차트를 가져왔어요.","여왕님은 환자분 중 가장 만족도가 높은 분이 되시겠네요."],"톰":["마계에도 담요가 있을까요. 없으면 제가 챙겨 오겠습니다.","딸이 이 얘기를 들으면 웃을 것 같아요."],"렌":["마계에 와서도 나는 굴복하지 않았다. 몸이 먼저 갔을 뿐이다.","이번 예약은 내가 먼저 걸었다. 기록해 둬라."],"카이단":["주인님, 마계 냄새 좋아요! 꼬리가 멈추질 않아요!","마계 정화방이 궁금해요! 같이 가요!"],"그로크":["마계 병사 여러분, 평가는 가혹하게 부탁드립니다.","로나 교관님이 보고 싶습니다. 오늘 평가는 몇 점일까요."],"이그니스":["업무다. 마계 설비도 정비하겠다.","마계 갑주는 천 한 장이라 장인으로서 마음이 아프구만."],"베르단":["장군은 마계에서도 정중하다.","족쇄 규정을 마계에 도입하겠다. 제1조는 3미터다."],"코그":["마계 장비는 해체할 가치가 높습니다! 설계도를 얻겠습니다!","신제품 「마계 연막탄」의 아이디어가 샘솟습니다!"],"루시안":["목줄이 있어서 마계에서도 안심입니다.","주인이 되는 것도 모범 노예의 길입니다."],"로제":["마계 병사 여러분, 건강 검진을 받으세요. 접수는 제가 하겠습니다.","오늘도 다녀오겠습니다. 마계 정화방은 어떨까요."],"핀":["마계도 불평할 거리가 많아. 의자가 너무 푹신해.","이 하늘이 갈라진 풍경은 왠지 설레. 불평은 이상 없어."],"벨루가":["마계 하늘은 날기 좋아! 깃털이 분홍색이야!","여왕님 날개는 나보다 크네! 같이 날자!"],"자하라":["마계 환율은 어떻게 되나요. 월정액 구독 신청받습니다.","여왕님과 계약하면 이득이 얼마일지 계산해 보겠습니다."]}};
